update public.saju_studios set (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website, updated_at) = ('moon-gate-saju-insadong','Moon Gate Saju','문게이트 사주','A gentle first reading off Insadong-gil','{"en":"A gentle first reading off Insadong-gil","ko":"인사동 골목에서 편하게 듣는 첫 사주","zh":"仁寺洞巷子里轻松的初次四柱体验","ja":"仁寺洞の路地で気軽に受ける初めての四柱推命","es":"Una primera lectura tranquila junto a Insadong-gil"}'::jsonb,'A second-floor room above a tea shop, set up for first-timers. The reader draws your chart on paper as she explains it, and an interpreter sits in for the whole session.','{"en":"A second-floor room above a tea shop, set up for first-timers. The reader draws your chart on paper as she explains it, and an interpreter sits in for the whole session.","ko":"찻집 2층에 자리한 첫 방문자를 위한 상담실입니다. 설명하면서 종이에 사주를 직접 그려 드리고, 통역사가 상담 내내 함께합니다.","zh":"位于茶馆二楼，专为初次体验者布置。老师会边讲解边在纸上画出您的命盘，全程有口译陪同。","ja":"茶屋の2階にある、初めての方向けの部屋です。説明しながら紙に命式を描き、通訳が最後まで同席します。","es":"Una sala en un segundo piso sobre una tetería, pensada para quien viene por primera vez. La lectora dibuja tu carta en papel mientras la explica y un intérprete acompaña toda la sesión."}'::jsonb,'active',true,true,true,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Insadong-gil, Jongno-gu','Seoul','Jongno-gu','Insadong',37.575196,126.983173,'Anguk',4,35000,'KRW',30,1,0,array['general','traditional_saju','career','wealth']::text[],array['saju']::text[],true,false,true,false,null,null,null, now()) where slug in ('demo-moon-gate','moon-gate-saju-insadong') and is_mock;
update public.saju_studios set (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website, updated_at) = ('seoul-starlight-tarot-hongdae','Seoul Starlight Tarot','서울 스타라이트 타로','Late-night tarot for love and life','{"en":"Late-night tarot for love and life","ko":"연애와 일상을 위한 심야 타로","zh":"为爱情与生活准备的深夜塔罗","ja":"恋愛と日常のための深夜タロット","es":"Tarot nocturno para el amor y la vida"}'::jsonb,'A small candlelit lounge two streets from Hongik Univ. Station, open until 11 pm at weekends. Most guests come for a quick tarot spread; add Saju if you want the bigger picture.','{"en":"A small candlelit lounge two streets from Hongik Univ. Station, open until 11 pm at weekends. Most guests come for a quick tarot spread; add Saju if you want the bigger picture.","ko":"홍대입구역에서 두 블록 떨어진 촛불 조명의 작은 라운지로, 주말에는 밤 11시까지 엽니다. 대부분 가볍게 타로를 보고, 큰 흐름이 궁금하면 사주를 더합니다.","zh":"距弘大入口站两条街的烛光小沙龙，周末营业到晚上11点。大多数客人来抽一次塔罗，想看整体走势可以加四柱。","ja":"弘大入口駅から2本裏の、キャンドルが灯る小さなラウンジ。週末は夜11時まで。多くの方は気軽にタロットを、大きな流れを知りたい方は四柱推命を追加します。","es":"Un pequeño salón a la luz de las velas a dos calles de la estación Hongik Univ., abierto hasta las 23 h los fines de semana. Casi todos vienen por una tirada rápida; añade Saju si quieres la visión general."}'::jsonb,'active',true,true,true,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Wausan-ro, Mapo-gu','Seoul','Mapo-gu','Hongdae',37.557038,126.921148,'Hongik Univ.',5,25000,'KRW',30,1,0,array['love','general']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null, now()) where slug in ('demo-seoul-starlight','seoul-starlight-tarot-hongdae') and is_mock;
update public.saju_studios set (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website, updated_at) = ('two-moons-atelier-seongsu','Two Moons Atelier','투문 아틀리에','Compatibility readings for two (or four)','{"en":"Compatibility readings for two (or four)","ko":"둘이, 또는 넷이 함께 보는 궁합","zh":"两人或四人一起的合盘解读","ja":"ふたりで、または4人で受ける相性占い","es":"Lecturas de compatibilidad para dos (o cuatro)"}'::jsonb,'A converted workshop in Seongsu with one long table, built for couples and friends. Each chart is drawn on a shared sheet so you can see where you match and where you pull apart.','{"en":"A converted workshop in Seongsu with one long table, built for couples and friends. Each chart is drawn on a shared sheet so you can see where you match and where you pull apart.","ko":"긴 테이블 하나를 둔 성수동의 공방을 개조한 공간으로, 커플과 친구를 위해 꾸몄습니다. 한 장에 모두의 사주를 그려 어디가 맞고 어디가 엇갈리는지 함께 봅니다.","zh":"由圣水洞工坊改造，只放一张长桌，专为情侣和朋友设计。所有人的命盘画在同一张纸上，一眼看出哪里契合、哪里相冲。","ja":"聖水洞の工房を改装した、長いテーブルひとつの空間。カップルや友人向けに、全員の命式を1枚に描いて相性を一緒に確かめます。","es":"Un antiguo taller en Seongsu con una única mesa larga, pensado para parejas y amigos. Las cartas se dibujan en una misma hoja para ver dónde encajáis y dónde os separáis."}'::jsonb,'active',true,true,true,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Yeonmujang-gil, Seongdong-gu','Seoul','Seongdong-gu','Seongsu',37.545084,127.052862,'Seongsu',6,90000,'KRW',50,4,0,array['compatibility','love','marriage']::text[],array['saju','compatibility']::text[],true,false,false,false,null,null,null, now()) where slug in ('demo-two-moons','two-moons-atelier-seongsu') and is_mock;

