insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('hanji-lamp-myeongri-bukchon','Hanji Lamp Myeongri','한지등 명리원','Thirty years of readings in a Bukchon hanok','{"en":"Thirty years of readings in a Bukchon hanok","ko":"북촌 한옥에서 30년을 이어 온 명리","zh":"在北村韩屋传承三十年的命理","ja":"北村の韓屋で30年続く命理","es":"Treinta años de lecturas en un hanok de Bukchon"}'::jsonb,'Readings take place on floor cushions in a restored hanok, lit by paper lamps. The master speaks Korean only; a trained interpreter joins every session and stays for your questions afterwards.','{"en":"Readings take place on floor cushions in a restored hanok, lit by paper lamps. The master speaks Korean only; a trained interpreter joins every session and stays for your questions afterwards.","ko":"복원한 한옥의 방석 위에서 한지등 불빛 아래 상담합니다. 선생님은 한국어로만 상담하며, 전문 통역사가 모든 상담에 함께하고 끝난 뒤 질문까지 도와 드립니다.","zh":"在修复后的韩屋里，坐在坐垫上、借着韩纸灯光进行解读。老师只说韩语，每次都有专业口译陪同，结束后也会帮您解答问题。","ja":"修復した韓屋で座布団に座り、韓紙の灯りのもとで鑑定します。先生は韓国語のみですが、専門の通訳が毎回同席し、終わった後の質問まで手伝います。","es":"Las lecturas se hacen sobre cojines en un hanok restaurado, a la luz de lámparas de papel. El maestro solo habla coreano; un intérprete formado acompaña cada sesión y se queda para tus preguntas."}'::jsonb,'active',true,true,true,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Bukchon-ro, Jongno-gu','Seoul','Jongno-gu','Bukchon',37.583502,126.981034,'Anguk',7,80000,'KRW',45,1,0,array['traditional_saju','general','timing']::text[],array['saju','naming']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('cloud-tea-saju-samcheong','Cloud Tea Saju','구름차 사주','Tea matched to your element, then your chart','{"en":"Tea matched to your element, then your chart","ko":"오행에 맞춘 차 한 잔, 그리고 사주","zh":"先喝一杯合您五行的茶，再看命盘","ja":"五行に合わせたお茶と、四柱推命","es":"Un té según tu elemento y después tu carta"}'::jsonb,'A quiet tea room up the hill in Samcheong-dong. Each reading starts with a pot of tea chosen for your chart, and the reader speaks some Japanese.','{"en":"A quiet tea room up the hill in Samcheong-dong. Each reading starts with a pot of tea chosen for your chart, and the reader speaks some Japanese.","ko":"삼청동 언덕 위의 조용한 찻방입니다. 사주에 맞춰 고른 차 한 주전자로 상담을 시작하며, 선생님은 일본어로도 조금 대화할 수 있습니다.","zh":"三清洞山坡上一间安静的茶室。每次解读都从一壶为您命盘挑选的茶开始，老师也会说一些日语。","ja":"三清洞の坂の上にある静かな茶室。命式に合わせて選んだお茶から始まり、先生は日本語も少し話せます。","es":"Una tranquila sala de té en la colina de Samcheong-dong. Cada lectura empieza con una tetera elegida para tu carta; la lectora habla algo de japonés."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Samcheong-ro, Jongno-gu','Seoul','Jongno-gu','Samcheong-dong',37.586254,126.978353,'Anguk',10,35000,'KRW',30,1,0,array['general','love','traditional_saju']::text[],array['saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('ikseon-fortune-room','Ikseon Fortune Room','익선 운세방','Quick, friendly readings in the hanok alleys','{"en":"Quick, friendly readings in the hanok alleys","ko":"한옥 골목에서 가볍게 보는 사주","zh":"韩屋小巷里轻松快速的四柱","ja":"韓屋の路地で気軽に受ける四柱推命","es":"Lecturas rápidas y cercanas entre callejones de hanok"}'::jsonb,'A tiny walk-in room in the middle of Ikseon-dong’s hanok lanes. Sessions run 30 minutes, the price is low, and face reading is a fun add-on for groups.','{"en":"A tiny walk-in room in the middle of Ikseon-dong’s hanok lanes. Sessions run 30 minutes, the price is low, and face reading is a fun add-on for groups.","ko":"익선동 한옥 골목 한가운데 있는 작은 상담방으로, 예약 없이도 들를 수 있습니다. 30분 상담에 가격도 부담 없고, 일행과 함께라면 관상도 재미있습니다.","zh":"位于益善洞韩屋小巷中间的小房间，可以直接走进来。每次30分钟，价格实惠，结伴来时加一个面相也很有趣。","ja":"益善洞の韓屋路地の真ん中にある小さな部屋で、予約なしでも入れます。30分で手頃な価格、グループなら観相も楽しめます。","es":"Una salita sin cita en pleno laberinto de hanok de Ikseon-dong. Sesiones de 30 minutos a buen precio; la lectura del rostro es un extra divertido en grupo."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Supyo-ro 28-gil, Jongno-gu','Seoul','Jongno-gu','Ikseon-dong',37.57374,126.987605,'Jongno 3-ga',3,25000,'KRW',30,1,0,array['general','love']::text[],array['saju','face_reading']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('seochon-ink-and-pillars','Ink & Pillars Seochon','서촌 먹과 기둥','Your four pillars, written in brush ink','{"en":"Your four pillars, written in brush ink","ko":"붓글씨로 써 드리는 나의 네 기둥","zh":"用毛笔写下您的四柱","ja":"あなたの四柱を筆で書きます","es":"Tus cuatro pilares, escritos a pincel"}'::jsonb,'A small studio near Gyeongbokgung where the reader writes your chart in calligraphy while explaining it. You leave with the sheet, signed and sealed.','{"en":"A small studio near Gyeongbokgung where the reader writes your chart in calligraphy while explaining it. You leave with the sheet, signed and sealed.","ko":"경복궁 근처의 작은 스튜디오로, 설명하면서 사주를 붓글씨로 써 드립니다. 낙관을 찍은 그 종이를 가져가실 수 있습니다.","zh":"景福宫附近的小工作室，老师一边讲解一边用书法写下您的命盘。结束后可带走盖好印章的那张纸。","ja":"景福宮近くの小さなスタジオ。説明しながら命式を書道で書き、落款を押したその紙をお持ち帰りいただけます。","es":"Un pequeño estudio cerca de Gyeongbokgung donde el lector escribe tu carta en caligrafía mientras la explica. Te llevas la hoja firmada y sellada."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Jahamun-ro, Jongno-gu','Seoul','Jongno-gu','Seochon',37.58055,126.967418,'Gyeongbokgung',5,55000,'KRW',50,1,0,array['career','traditional_saju','study']::text[],array['saju','naming']::text[],false,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('myeongdong-golden-hour-saju','Golden Hour Saju','황금시 사주','Readings in Mandarin or Korean, steps from the station','{"en":"Readings in Mandarin or Korean, steps from the station","ko":"역 바로 앞, 중국어·한국어 상담","zh":"地铁站旁，中文或韩语解读","ja":"駅すぐ、中国語・韓国語で鑑定","es":"Lecturas en mandarín o coreano a pasos de la estación"}'::jsonb,'An easy-to-find studio on the third floor of a Myeongdong side-street building, with a lift. One reader works in Mandarin; interpreters cover English and Japanese.','{"en":"An easy-to-find studio on the third floor of a Myeongdong side-street building, with a lift. One reader works in Mandarin; interpreters cover English and Japanese.","ko":"명동 골목 건물 3층에 있어 찾기 쉽고 엘리베이터가 있습니다. 한 선생님은 중국어로 상담하며, 영어와 일본어는 통역사가 함께합니다.","zh":"位于明洞小巷大楼三楼，好找且有电梯。一位老师用中文解读，英语和日语有口译。","ja":"明洞の路地にあるビルの3階で見つけやすく、エレベーターもあります。中国語で鑑定する先生がいて、英語と日本語は通訳がつきます。","es":"Un estudio fácil de encontrar en el tercer piso de un edificio de una bocacalle de Myeongdong, con ascensor. Una lectora trabaja en mandarín; hay intérpretes de inglés y japonés."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Myeongdong-gil, Jung-gu','Seoul','Jung-gu','Myeongdong',37.565142,126.982244,'Myeongdong',3,35000,'KRW',30,1,0,array['general','wealth','love']::text[],array['saju']::text[],true,true,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('euljiro-neon-oracle','Neon Oracle Euljiro','을지로 네온 점집','Tarot in a retro printing alley, open late','{"en":"Tarot in a retro printing alley, open late","ko":"레트로 인쇄 골목의 심야 타로","zh":"复古印刷巷里的深夜塔罗","ja":"レトロな印刷路地の深夜タロット","es":"Tarot en un callejón de imprentas retro, abierto tarde"}'::jsonb,'Above an old print shop in Euljiro, under neon and vintage posters. Drop in after dinner for a 30-minute spread, or book the combo to add your Saju.','{"en":"Above an old print shop in Euljiro, under neon and vintage posters. Drop in after dinner for a 30-minute spread, or book the combo to add your Saju.","ko":"을지로의 오래된 인쇄소 위층, 네온과 빈티지 포스터 아래에서 상담합니다. 저녁 먹고 들러 30분 타로를 보거나, 사주를 더한 콤보를 예약하세요.","zh":"在乙支路老印刷厂楼上，霓虹灯和复古海报下。晚饭后来抽30分钟塔罗，或预约加上四柱的套餐。","ja":"乙支路の古い印刷所の上階、ネオンとヴィンテージポスターの下で。夕食後に30分のタロット、または四柱推命付きのセットもどうぞ。","es":"Sobre una vieja imprenta de Euljiro, entre neones y carteles antiguos. Pásate después de cenar para una tirada de 30 minutos o reserva el combo con tu Saju."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Eulji-ro, Jung-gu','Seoul','Jung-gu','Euljiro',37.566938,126.98931,'Euljiro 3-ga',2,25000,'KRW',30,1,0,array['general','career','love']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('dongdaemun-five-elements-house','Five Elements House','오행당','Practical readings from a market-district veteran','{"en":"Practical readings from a market-district veteran","ko":"시장 상인들이 찾는 현실적인 사주","zh":"市场商人常去的务实四柱","ja":"市場の商人に人気の実践的な四柱推命","es":"Lecturas prácticas de un veterano del barrio de mercados"}'::jsonb,'A no-frills room near DDP that market traders have used for years. Good value, step-free access, and an interpreter on hand for English and Mandarin.','{"en":"A no-frills room near DDP that market traders have used for years. Good value, step-free access, and an interpreter on hand for English and Mandarin.","ko":"시장 상인들이 오랫동안 찾아온 DDP 근처의 소박한 상담실입니다. 가격이 합리적이고 턱 없는 출입이 가능하며, 영어·중국어 통역사가 있습니다.","zh":"DDP附近一间朴素的房间，市场商人光顾多年。价格实惠，无障碍出入，有英语和中文口译。","ja":"DDP近くの飾らない部屋で、市場の商人が長年通っています。手頃な価格で段差がなく、英語・中国語の通訳がいます。","es":"Una sala sencilla cerca del DDP a la que los comerciantes del mercado van desde hace años. Buen precio, acceso sin escalones e intérprete de inglés y mandarín."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Jangchungdan-ro, Jung-gu','Seoul','Jung-gu','Dongdaemun',37.567114,127.00655,'Dongdaemun History & Culture Park',5,25000,'KRW',30,1,0,array['general','wealth','business']::text[],array['saju']::text[],true,true,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('yeonnam-paper-moon','Paper Moon Yeonnam','연남 종이달','English-first Saju and tarot near Gyeongui Line Forest Park','{"en":"English-first Saju and tarot near Gyeongui Line Forest Park","ko":"경의선숲길 옆, 영어로 듣는 사주와 타로","zh":"京义线林荫道旁，英语四柱与塔罗","ja":"京義線の森の道のそば、英語で受ける四柱とタロット","es":"Saju y tarot en inglés junto al parque Gyeongui Line"}'::jsonb,'A sunny upstairs room on a quiet Yeonnam street. The reader grew up in LA, so sessions run in English without an interpreter, and groups of up to four can share a reading.','{"en":"A sunny upstairs room on a quiet Yeonnam street. The reader grew up in LA, so sessions run in English without an interpreter, and groups of up to four can share a reading.","ko":"연남동 조용한 거리의 햇살 좋은 2층 방입니다. 선생님이 LA에서 자라 통역 없이 영어로 상담하며, 최대 4명까지 함께 들을 수 있습니다.","zh":"延南洞安静街道上一间阳光充足的二楼房间。老师在洛杉矶长大，无需口译直接用英语解读，最多4人可一起听。","ja":"延南洞の静かな通りにある日当たりの良い2階の部屋。先生はLA育ちで通訳なしの英語で鑑定し、最大4名まで一緒に受けられます。","es":"Una sala luminosa en un primer piso de una calle tranquila de Yeonnam. La lectora creció en Los Ángeles, así que la sesión es en inglés sin intérprete; hasta cuatro personas pueden compartirla."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Donggyo-ro, Mapo-gu','Seoul','Mapo-gu','Yeonnam-dong',37.562929,126.92132,'Hongik Univ.',8,55000,'KRW',50,4,0,array['love','general','compatibility']::text[],array['saju','tarot']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('mangwon-riverside-saju','Riverside Saju Mangwon','망원 강변 사주','A neighbourhood reader near Mangwon Market','{"en":"A neighbourhood reader near Mangwon Market","ko":"망원시장 옆 동네 사주 선생님","zh":"望远市场旁的街坊四柱老师","ja":"望遠市場のそばの町の四柱推命師","es":"Una lectora de barrio junto al mercado de Mangwon"}'::jsonb,'A small ground-floor studio a short walk from the Han River. Sessions are in Korean with live AI interpretation on a tablet, which keeps prices low.','{"en":"A small ground-floor studio a short walk from the Han River. Sessions are in Korean with live AI interpretation on a tablet, which keeps prices low.","ko":"한강까지 걸어갈 수 있는 1층의 작은 스튜디오입니다. 한국어로 상담하고 태블릿으로 AI 실시간 통역을 제공해 가격을 낮췄습니다.","zh":"离汉江步行不远的一楼小工作室。用韩语解读，并用平板提供AI实时口译，因此价格较低。","ja":"漢江まで歩ける1階の小さなスタジオ。韓国語で鑑定し、タブレットのAIリアルタイム通訳を使うので価格を抑えています。","es":"Un pequeño estudio a pie de calle a un paseo del río Han. Las sesiones son en coreano con interpretación por IA en una tableta, lo que mantiene los precios bajos."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Poeun-ro, Mapo-gu','Seoul','Mapo-gu','Mangwon',37.557113,126.898166,'Mangwon',6,25000,'KRW',30,1,0,array['general','love','year_ahead']::text[],array['saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('sinchon-campus-tarot','Campus Tarot & Saju','캠퍼스 타로사주','Student-friendly readings by the universities','{"en":"Student-friendly readings by the universities","ko":"대학가에서 부담 없이 보는 타로·사주","zh":"大学城里学生也负担得起的解读","ja":"大学街で気軽に受けるタロット・四柱推命","es":"Lecturas para estudiantes junto a las universidades"}'::jsonb,'Between Yonsei and Ewha, with student pricing in the afternoon. Questions about exams, job hunting and studying abroad are the house speciality.','{"en":"Between Yonsei and Ewha, with student pricing in the afternoon. Questions about exams, job hunting and studying abroad are the house speciality.","ko":"연세대와 이화여대 사이에 있으며 오후에는 학생 할인가로 상담합니다. 시험, 취업, 유학 고민을 특히 많이 봅니다.","zh":"位于延世大学和梨花女子大学之间，下午有学生价。最擅长考试、求职和留学问题。","ja":"延世大と梨花女子大の間にあり、午後は学生価格です。試験、就職活動、留学の相談が得意です。","es":"Entre Yonsei y Ewha, con precio para estudiantes por la tarde. La especialidad de la casa: exámenes, búsqueda de empleo y estudiar fuera."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Yonsei-ro, Seodaemun-gu','Seoul','Seodaemun-gu','Sinchon',37.555826,126.934443,'Sinchon',4,25000,'KRW',30,1,0,array['career','study','love']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('itaewon-crossroads-readings','Crossroads Readings','크로스로드 상담소','For big moves, in English, Spanish or Korean','{"en":"For big moves, in English, Spanish or Korean","ko":"인생의 큰 결정을 영어·스페인어·한국어로","zh":"人生重大决定，可用英语、西语或韩语","ja":"人生の大きな決断を英語・スペイン語・韓国語で","es":"Para grandes cambios, en inglés, español o coreano"}'::jsonb,'A relaxed studio up the hill from Itaewon Station that sees a lot of expats and long-stay visitors. Bring the decision you are weighing: a new job, a move, a relationship.','{"en":"A relaxed studio up the hill from Itaewon Station that sees a lot of expats and long-stay visitors. Bring the decision you are weighing: a new job, a move, a relationship.","ko":"이태원역 언덕 위의 편안한 스튜디오로 외국인 거주자와 장기 체류자가 많이 찾습니다. 이직, 이사, 관계처럼 고민 중인 결정을 가져오세요.","zh":"梨泰院站上坡处一间轻松的工作室，常有外籍居民和长期旅居者来访。带上您正在权衡的决定：新工作、搬家或一段关系。","ja":"梨泰院駅から坂を上がったところにある気楽なスタジオで、在住外国人や長期滞在者がよく訪れます。転職、引っ越し、恋愛など迷っている決断を持ってきてください。","es":"Un estudio tranquilo cuesta arriba desde la estación de Itaewon, con muchos expatriados y visitantes de larga estancia. Trae la decisión que estás sopesando: un trabajo, una mudanza, una relación."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Itaewon-ro, Yongsan-gu','Seoul','Yongsan-gu','Itaewon',37.535813,126.992563,'Itaewon',4,55000,'KRW',50,1,0,array['career','relocation','love']::text[],array['saju','tarot']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('hannam-quiet-hour','The Quiet Hour Hannam','한남 고요한 시간','Private consultations for career and business timing','{"en":"Private consultations for career and business timing","ko":"커리어와 사업 시기를 위한 프라이빗 상담","zh":"为事业与生意时机准备的私人咨询","ja":"キャリアと事業のタイミングのための個別相談","es":"Consultas privadas sobre carrera y momentos de negocio"}'::jsonb,'An appointment-only room in a Hannam-dong townhouse. Sessions are long and unhurried, with a human interpreter, and finish with a written summary of the years ahead.','{"en":"An appointment-only room in a Hannam-dong townhouse. Sessions are long and unhurried, with a human interpreter, and finish with a written summary of the years ahead.","ko":"한남동 타운하우스의 예약제 상담실입니다. 전문 통역사와 함께 여유 있게 길게 상담하고, 앞으로의 흐름을 정리한 요약지를 드립니다.","zh":"位于汉南洞联排别墅的预约制咨询室。由专业口译陪同，时间充裕，最后附上未来几年的书面总结。","ja":"漢南洞のタウンハウスにある予約制の部屋。通訳付きでゆったり時間をかけ、最後にこれからの流れをまとめた書面をお渡しします。","es":"Una sala solo con cita en una casa adosada de Hannam-dong. Sesiones largas y sin prisas, con intérprete, que terminan con un resumen escrito de los próximos años."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Dokseodang-ro, Yongsan-gu','Seoul','Yongsan-gu','Hannam-dong',37.535809,127.003206,'Hangangjin',6,80000,'KRW',45,1,0,array['career','wealth','timing','business']::text[],array['saju']::text[],false,true,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('seongsu-element-lab','Element Lab Seongsu','성수 오행연구소','Your element balance, visualised','{"en":"Your element balance, visualised","ko":"나의 오행 균형을 한눈에","zh":"一眼看懂您的五行平衡","ja":"あなたの五行バランスを可視化","es":"El equilibrio de tus elementos, en un gráfico"}'::jsonb,'A bright studio in a converted Seongsu warehouse. Your chart is shown on screen as an element balance you can photograph, and the Korean name session is a popular souvenir.','{"en":"A bright studio in a converted Seongsu warehouse. Your chart is shown on screen as an element balance you can photograph, and the Korean name session is a popular souvenir.","ko":"성수동 창고를 개조한 밝은 스튜디오입니다. 사주를 오행 균형 도표로 화면에 보여 드려 사진으로 남길 수 있고, 한국 이름 짓기는 기념품으로 인기가 많습니다.","zh":"由圣水洞仓库改造的明亮工作室。命盘以五行平衡图显示在屏幕上，可以拍照留念；韩文取名也是热门纪念。","ja":"聖水洞の倉庫を改装した明るいスタジオ。命式を五行バランスの図で画面に映すので写真に残せ、韓国名づけはお土産として人気です。","es":"Un estudio luminoso en un almacén reformado de Seongsu. Tu carta aparece en pantalla como un gráfico de elementos que puedes fotografiar; el nombre coreano es un recuerdo muy popular."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Yeonmujang-gil, Seongdong-gu','Seoul','Seongdong-gu','Seongsu',37.54268,127.057243,'Seongsu',4,35000,'KRW',30,1,0,array['general','traditional_saju','career']::text[],array['saju','naming']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('gangnam-compass-myeongri','Compass Myeongri Gangnam','강남 나침반 명리','Senior masters for career, money and partnerships','{"en":"Senior masters for career, money and partnerships","ko":"커리어·재물·궁합을 보는 베테랑 명리","zh":"资深命理师解读事业、财运与合盘","ja":"キャリア・金運・相性を見るベテラン命理師","es":"Maestros veteranos para carrera, dinero y pareja"}'::jsonb,'A polished consultation suite near Gangnam Station with two readers and full-time interpreters for English, Mandarin and Japanese. Book ahead; evenings fill first.','{"en":"A polished consultation suite near Gangnam Station with two readers and full-time interpreters for English, Mandarin and Japanese. Book ahead; evenings fill first.","ko":"강남역 근처의 깔끔한 상담실로 두 명의 상담가와 영어·중국어·일본어 상주 통역사가 있습니다. 저녁 시간이 먼저 차니 미리 예약하세요.","zh":"江南站附近一间精致的咨询室，两位老师，并有常驻英语、中文、日语口译。晚间时段最先约满，请提前预约。","ja":"江南駅近くの洗練された相談室で、鑑定士が2名、英語・中国語・日本語の常勤通訳がいます。夜の枠から埋まるので早めのご予約を。","es":"Una elegante suite de consulta cerca de la estación de Gangnam, con dos lectores e intérpretes fijos de inglés, mandarín y japonés. Reserva con antelación; las tardes se llenan primero."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Teheran-ro, Gangnam-gu','Seoul','Gangnam-gu','Gangnam',37.498551,127.023989,'Gangnam',4,80000,'KRW',45,2,0,array['career','wealth','compatibility','business']::text[],array['saju','compatibility']::text[],true,true,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('garosu-gil-blossom-tarot','Blossom Tarot Garosu-gil','가로수길 블라썸 타로','Tarot and couple readings in Japanese or Korean','{"en":"Tarot and couple readings in Japanese or Korean","ko":"일본어·한국어로 보는 타로와 커플 궁합","zh":"可用日语或韩语的塔罗与情侣合盘","ja":"日本語・韓国語でタロットとカップル相性","es":"Tarot y compatibilidad de pareja en japonés o coreano"}'::jsonb,'A pretty, flower-filled room off Garosu-gil. One reader is from Osaka and works in Japanese; couples often book the combined tarot and compatibility session.','{"en":"A pretty, flower-filled room off Garosu-gil. One reader is from Osaka and works in Japanese; couples often book the combined tarot and compatibility session.","ko":"가로수길 옆 꽃으로 가득한 예쁜 방입니다. 한 선생님은 오사카 출신으로 일본어로 상담하며, 커플은 타로와 궁합을 함께 보는 상담을 많이 예약합니다.","zh":"新沙洞林荫道旁一间满是鲜花的漂亮房间。一位老师来自大阪，用日语解读；情侣常预约塔罗加合盘。","ja":"カロスキル脇の花でいっぱいの可愛い部屋。大阪出身の先生が日本語で鑑定し、カップルはタロットと相性のセットをよく予約します。","es":"Una sala bonita y llena de flores junto a Garosu-gil. Una lectora es de Osaka y trabaja en japonés; las parejas suelen reservar tarot y compatibilidad juntos."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Garosu-gil, Gangnam-gu','Seoul','Gangnam-gu','Sinsa',37.521512,127.021735,'Sinsa',6,30000,'KRW',30,2,0,array['love','compatibility','general']::text[],array['tarot','saju','compatibility']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('apgujeong-white-crane','White Crane Myeongri','백학 명리원','Marriage timing and wedding dates, a family practice','{"en":"Marriage timing and wedding dates, a family practice","ko":"대를 이어 온 결혼운과 택일","zh":"家族传承的婚期与择日","ja":"代々続く結婚運と日取り選び","es":"Momento de casarse y fecha de boda, una tradición familiar"}'::jsonb,'A second-generation studio in Apgujeong, best known for marriage readings and choosing auspicious wedding dates. Couples are welcome to come together.','{"en":"A second-generation studio in Apgujeong, best known for marriage readings and choosing auspicious wedding dates. Couples are welcome to come together.","ko":"압구정에서 2대째 이어 온 상담소로 결혼운과 길일 택일로 잘 알려져 있습니다. 커플이 함께 오셔도 좋습니다.","zh":"压鸥亭一家传承两代的命理馆，以婚姻运和挑选结婚吉日闻名。欢迎情侣一同前来。","ja":"狎鴎亭で2代続く鑑定所で、結婚運と吉日選びで知られています。カップルでのご来店も歓迎です。","es":"Un estudio de segunda generación en Apgujeong, conocido por las lecturas de matrimonio y por elegir fechas propicias para la boda. Las parejas pueden venir juntas."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Apgujeong-ro, Gangnam-gu','Seoul','Gangnam-gu','Apgujeong',37.527336,127.026618,'Apgujeong Rodeo',5,90000,'KRW',50,2,0,array['traditional_saju','marriage','compatibility']::text[],array['saju','naming','compatibility']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('jamsil-lakeside-fortune','Lakeside Fortune Jamsil','잠실 호숫가 운세','Family-friendly readings by Seokchon Lake','{"en":"Family-friendly readings by Seokchon Lake","ko":"석촌호수 옆, 가족과 함께 보는 사주","zh":"石村湖旁，适合全家的四柱","ja":"石村湖のそば、家族で受けられる四柱推命","es":"Lecturas para toda la familia junto al lago Seokchon"}'::jsonb,'A step-free studio a short walk from Lotte World and Seokchon Lake. Groups of up to four can share a session, which makes it popular with families on holiday.','{"en":"A step-free studio a short walk from Lotte World and Seokchon Lake. Groups of up to four can share a session, which makes it popular with families on holiday.","ko":"롯데월드와 석촌호수에서 가까운 턱 없는 스튜디오입니다. 최대 4명까지 함께 상담할 수 있어 여행 중인 가족에게 인기가 많습니다.","zh":"离乐天世界和石村湖步行不远的无障碍工作室。最多4人可一起解读，很受度假家庭欢迎。","ja":"ロッテワールドと石村湖から歩ける段差のないスタジオ。最大4名まで一緒に受けられるので、旅行中の家族に人気です。","es":"Un estudio sin escalones a un paseo de Lotte World y el lago Seokchon. Hasta cuatro personas pueden compartir sesión, por eso gusta a las familias de vacaciones."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Olympic-ro, Songpa-gu','Seoul','Songpa-gu','Jamsil',37.511946,127.095141,'Jamsil',7,35000,'KRW',30,4,0,array['general','year_ahead','career']::text[],array['saju']::text[],true,true,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('yeouido-market-hours-saju','Market Hours Saju','여의도 장시간 사주','Lunch-hour readings in the financial district','{"en":"Lunch-hour readings in the financial district","ko":"금융가 직장인을 위한 점심시간 사주","zh":"金融区上班族的午休四柱","ja":"金融街の会社員向けランチタイム鑑定","es":"Lecturas a la hora de comer en el distrito financiero"}'::jsonb,'Weekday-only and built around the lunch hour. Expect focused 45- to 50-minute readings on career moves, money and the year ahead.','{"en":"Weekday-only and built around the lunch hour. Expect focused 45- to 50-minute readings on career moves, money and the year ahead.","ko":"평일에만 열고 점심시간에 맞춰 운영합니다. 이직, 재물, 신년운을 45~50분 동안 집중해서 봅니다.","zh":"只在工作日营业，围绕午休时间安排。45至50分钟专注解读跳槽、财运和来年运势。","ja":"平日のみ、お昼休みに合わせて営業。転職、金運、年運を45〜50分で集中して読みます。","es":"Solo entre semana y pensado para la hora de comer. Lecturas centradas de 45 a 50 minutos sobre cambios de trabajo, dinero y el año que viene."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Yeoui-daero, Yeongdeungpo-gu','Seoul','Yeongdeungpo-gu','Yeouido',37.523409,126.921689,'Yeouido',6,50000,'KRW',45,1,0,array['career','wealth','business']::text[],array['saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('insadong-old-almanac','The Old Almanac','옛 책력방','Old almanacs and patient explanations','{"en":"Old almanacs and patient explanations","ko":"옛 책력과 차근차근한 설명","zh":"古老历书与耐心讲解","ja":"古い暦と丁寧な説明","es":"Almanaques antiguos y explicaciones pacientes"}'::jsonb,'A room lined with old almanacs and books, tucked behind the main Insadong street. Readings are in Korean with AI interpretation, at one of the lowest prices in the area.','{"en":"A room lined with old almanacs and books, tucked behind the main Insadong street. Readings are in Korean with AI interpretation, at one of the lowest prices in the area.","ko":"인사동 큰길 뒤편, 옛 책력과 책이 가득한 방입니다. 한국어로 상담하고 AI 통역을 제공하며 이 동네에서 가장 저렴한 편입니다.","zh":"藏在仁寺洞主街背后、摆满古老历书和书籍的房间。用韩语解读并提供AI口译，价格是这一带最低之一。","ja":"仁寺洞の大通りの裏にある、古い暦や本が並ぶ部屋。韓国語の鑑定にAI通訳つきで、この界隈で最も手頃な価格のひとつです。","es":"Una sala llena de almanaques y libros antiguos, escondida tras la calle principal de Insadong. Lecturas en coreano con interpretación por IA, de las más baratas de la zona."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Insadong-gil, Jongno-gu','Seoul','Jongno-gu','Insadong',37.571776,126.986181,'Anguk',5,25000,'KRW',30,1,0,array['traditional_saju','general']::text[],array['saju','face_reading']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('bukchon-morning-bell','Morning Bell Saju','새벽종 사주','Morning readings in a hanok guesthouse','{"en":"Morning readings in a hanok guesthouse","ko":"한옥 게스트하우스의 아침 사주","zh":"韩屋民宿里的早晨四柱","ja":"韓屋ゲストハウスで朝の四柱推命","es":"Lecturas matinales en una casa de huéspedes hanok"}'::jsonb,'Readings in the courtyard room of a family-run hanok guesthouse, mostly at weekends. Japanese and English interpreters can be booked in advance.','{"en":"Readings in the courtyard room of a family-run hanok guesthouse, mostly at weekends. Japanese and English interpreters can be booked in advance.","ko":"가족이 운영하는 한옥 게스트하우스의 마당 쪽 방에서 주로 주말에 상담합니다. 일본어·영어 통역사는 미리 예약할 수 있습니다.","zh":"在家庭经营的韩屋民宿庭院旁房间解读，主要在周末。日语和英语口译可提前预约。","ja":"家族経営の韓屋ゲストハウスの中庭側の部屋で、主に週末に鑑定します。日本語・英語の通訳は事前予約制です。","es":"Lecturas en la habitación del patio de una casa de huéspedes hanok familiar, sobre todo los fines de semana. Se puede reservar intérprete de japonés o inglés."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Bukchon-ro, Jongno-gu','Seoul','Jongno-gu','Bukchon',37.580593,126.985075,'Anguk',8,50000,'KRW',45,1,0,array['general','love','year_ahead']::text[],array['saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('hongdae-cosmic-diner','Cosmic Diner Tarot','코스믹 다이너 타로','Tarot nights for friend groups','{"en":"Tarot nights for friend groups","ko":"친구들과 함께하는 타로의 밤","zh":"和朋友一起的塔罗之夜","ja":"友だちと楽しむタロットナイト","es":"Noches de tarot para grupos de amigos"}'::jsonb,'A retro diner-themed room near Hongdae’s busking street, open late. Book the group session for up to four friends, or drop in for a quick spread.','{"en":"A retro diner-themed room near Hongdae’s busking street, open late. Book the group session for up to four friends, or drop in for a quick spread.","ko":"홍대 버스킹 거리 근처, 늦게까지 여는 레트로 다이너 콘셉트의 방입니다. 최대 4명 단체 상담을 예약하거나 가볍게 들러 타로를 보세요.","zh":"弘大街头表演区附近、营业到很晚的复古餐厅风格房间。可预约最多4人的团体场，或随时进来抽一次。","ja":"弘大のバスキング通り近くにある、夜遅くまで開いているレトロなダイナー風の部屋。最大4名のグループ枠を予約するか、気軽に立ち寄ってどうぞ。","es":"Una sala con estética de diner retro cerca de la calle de músicos callejeros de Hongdae, abierta hasta tarde. Reserva la sesión de grupo para hasta cuatro amigos o pásate para una tirada rápida."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Wausan-ro, Mapo-gu','Seoul','Mapo-gu','Hongdae',37.553923,126.925342,'Hongik Univ.',3,25000,'KRW',30,4,0,array['love','general','compatibility']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('myeongdong-jade-pavilion','Jade Pavilion Saju','옥정 사주','Detailed wealth readings in Mandarin','{"en":"Detailed wealth readings in Mandarin","ko":"중국어로 듣는 꼼꼼한 재물운","zh":"用中文详细解读财运","ja":"中国語で受ける詳しい金運鑑定","es":"Lecturas detalladas sobre dinero en mandarín"}'::jsonb,'A formal consultation room near Myeongdong Cathedral. The master is from Taipei and reads directly in Mandarin, with interpreters for Japanese and English.','{"en":"A formal consultation room near Myeongdong Cathedral. The master is from Taipei and reads directly in Mandarin, with interpreters for Japanese and English.","ko":"명동성당 근처의 격식 있는 상담실입니다. 타이베이 출신 선생님이 중국어로 직접 상담하고, 일본어와 영어는 통역사가 함께합니다.","zh":"明洞圣堂附近一间正式的咨询室。老师来自台北，直接用中文解读，日语和英语有口译。","ja":"明洞聖堂近くの格式ある相談室。台北出身の先生が中国語で直接鑑定し、日本語と英語は通訳がつきます。","es":"Una sala de consulta formal cerca de la catedral de Myeongdong. La maestra es de Taipéi y lee directamente en mandarín, con intérpretes de japonés e inglés."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Myeongdong-gil, Jung-gu','Seoul','Jung-gu','Myeongdong',37.561326,126.987055,'Myeongdong',4,80000,'KRW',45,2,0,array['wealth','compatibility','traditional_saju']::text[],array['saju','naming']::text[],false,true,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('euljiro-red-thread','Red Thread Compatibility','붉은실 궁합소','Relationships only: couples, crushes and exes','{"en":"Relationships only: couples, crushes and exes","ko":"연애 전문: 커플, 짝사랑, 그리고 전 연인","zh":"只看感情：情侣、暗恋与前任","ja":"恋愛専門：カップル、片思い、元恋人","es":"Solo relaciones: parejas, flechazos y ex"}'::jsonb,'A small studio near Euljiro’s old lighting shops that reads relationships and nothing else. Couples can come together; solo guests can bring a partner’s birth date.','{"en":"A small studio near Euljiro’s old lighting shops that reads relationships and nothing else. Couples can come together; solo guests can bring a partner’s birth date.","ko":"을지로 조명 상가 근처의 작은 스튜디오로 오직 연애만 봅니다. 커플이 함께 와도 되고, 혼자라면 상대의 생년월일만 가져오셔도 됩니다.","zh":"乙支路老灯具街附近的小工作室，只看感情。情侣可以一起来，单独来也可以带上对方的生日。","ja":"乙支路の照明街近くにある、恋愛だけを見る小さなスタジオ。カップルで来ても、ひとりで相手の生年月日を持ってきても大丈夫です。","es":"Un pequeño estudio junto a las antiguas tiendas de lámparas de Euljiro que solo lee relaciones. Las parejas pueden venir juntas; si vienes solo, trae la fecha de nacimiento de la otra persona."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Eulji-ro, Jung-gu','Seoul','Jung-gu','Euljiro',37.564976,126.993029,'Euljiro 3-ga',4,35000,'KRW',30,2,0,array['compatibility','love','marriage']::text[],array['saju','compatibility']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('samcheong-mountain-view','Mountain View Myeongri','산경 명리','Classical myeongri with a view of Bugaksan','{"en":"Classical myeongri with a view of Bugaksan","ko":"북악산이 보이는 정통 명리","zh":"可眺望北岳山的正统命理","ja":"北岳山を望む正統派の命理","es":"Myeongri clásico con vistas al Bugaksan"}'::jsonb,'At the top of Samcheong-dong with a window onto the mountain. Long, classical readings with a human interpreter; worth the uphill walk.','{"en":"At the top of Samcheong-dong with a window onto the mountain. Long, classical readings with a human interpreter; worth the uphill walk.","ko":"삼청동 꼭대기, 창밖으로 산이 보이는 곳입니다. 통역사와 함께 길고 정통적인 상담을 받을 수 있어 언덕길을 오를 만합니다.","zh":"位于三清洞最高处，窗外就是山景。由口译陪同的长时间正统解读，值得爬坡前往。","ja":"三清洞のいちばん上、窓から山が見える場所。通訳付きで長く正統派の鑑定が受けられ、坂を上る価値があります。","es":"En lo alto de Samcheong-dong, con una ventana a la montaña. Lecturas clásicas y largas con intérprete; merece la pena la cuesta."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Samcheong-ro, Jongno-gu','Seoul','Jongno-gu','Samcheong-dong',37.584474,126.981904,'Anguk',12,80000,'KRW',45,1,0,array['traditional_saju','timing','career']::text[],array['saju']::text[],false,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('seongsu-moonrise-tarot','Moonrise Tarot Seongsu','성수 월출 타로','Tarot with a hand-painted deck','{"en":"Tarot with a hand-painted deck","ko":"직접 그린 카드로 보는 타로","zh":"手绘牌组的塔罗","ja":"手描きのカードで占うタロット","es":"Tarot con una baraja pintada a mano"}'::jsonb,'A small studio inside a Seongsu design shop. The reader paints her own cards; evenings are busiest, so book if you are coming after 7 pm.','{"en":"A small studio inside a Seongsu design shop. The reader paints her own cards; evenings are busiest, so book if you are coming after 7 pm.","ko":"성수동 디자인 숍 안의 작은 스튜디오입니다. 선생님이 직접 그린 카드를 쓰며 저녁이 가장 붐비니 7시 이후라면 예약하세요.","zh":"位于圣水洞一家设计店内的小工作室。老师使用自己手绘的牌；晚上最忙，7点后前来请预约。","ja":"聖水洞のデザインショップの中にある小さなスタジオ。先生が自分で描いたカードを使います。夜が混むので19時以降は予約がおすすめです。","es":"Un pequeño estudio dentro de una tienda de diseño de Seongsu. La lectora pinta sus propias cartas; las tardes son lo más lleno, así que reserva si vienes después de las 19 h."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Yeonmujang-gil, Seongdong-gu','Seoul','Seongdong-gu','Seongsu',37.54578,127.056468,'Seongsu',5,25000,'KRW',30,1,0,array['love','career','general']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('gangnam-blue-hour-saju','Blue Hour Saju','블루아워 사주','After-work readings near Gangnam Station','{"en":"After-work readings near Gangnam Station","ko":"강남역 근처 퇴근 후 사주","zh":"江南站附近的下班后四柱","ja":"江南駅近くで仕事帰りの四柱推命","es":"Lecturas después del trabajo cerca de la estación de Gangnam"}'::jsonb,'Open until 10 pm for people coming straight from the office. Short readings on love and work, with tarot if you want a second opinion.','{"en":"Open until 10 pm for people coming straight from the office. Short readings on love and work, with tarot if you want a second opinion.","ko":"퇴근 후 바로 오는 분들을 위해 밤 10시까지 엽니다. 연애와 일에 대한 짧은 상담에, 다른 시각이 필요하면 타로도 더할 수 있습니다.","zh":"营业到晚上10点，方便下班直接过来。简短解读感情和工作，想听第二种意见可以加塔罗。","ja":"仕事帰りに寄れるよう夜10時まで営業。恋愛と仕事の短い鑑定に、別の視点が欲しければタロットも追加できます。","es":"Abierto hasta las 22 h para quien viene directo de la oficina. Lecturas cortas sobre amor y trabajo, con tarot si quieres una segunda opinión."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Teheran-ro, Gangnam-gu','Seoul','Gangnam-gu','Gangnam',37.495859,127.028551,'Gangnam',6,35000,'KRW',30,1,0,array['love','career','general']::text[],array['saju','tarot']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('itaewon-hilltop-names','Hilltop Korean Names','언덕 위 이름집','A Korean name that fits your chart','{"en":"A Korean name that fits your chart","ko":"내 사주에 맞는 한국 이름","zh":"契合您命盘的韩文名字","ja":"あなたの命式に合う韓国名","es":"Un nombre coreano que encaja con tu carta"}'::jsonb,'Specialises in Korean names for visitors and overseas Koreans, chosen to balance your elements. You leave with your name written in hangul and hanja.','{"en":"Specialises in Korean names for visitors and overseas Koreans, chosen to balance your elements. You leave with your name written in hangul and hanja.","ko":"방문객과 해외 동포를 위해 오행의 균형을 맞춘 한국 이름을 전문으로 짓습니다. 한글과 한자로 쓴 이름 카드를 가져가실 수 있습니다.","zh":"专为游客和海外韩侨取韩文名字，兼顾五行平衡。结束后可带走用韩文和汉字写成的名字卡。","ja":"旅行者や海外コリアンのために、五行のバランスを整える韓国名を専門に考えます。ハングルと漢字で書いた名前カードをお持ち帰りいただけます。","es":"Especialistas en nombres coreanos para visitantes y coreanos en el extranjero, elegidos para equilibrar tus elementos. Te llevas tu nombre escrito en hangul y hanja."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Itaewon-ro, Yongsan-gu','Seoul','Yongsan-gu','Itaewon',37.532066,126.995526,'Itaewon',7,35000,'KRW',30,1,0,array['general','traditional_saju']::text[],array['naming','saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('sinsa-silk-road-saju','Silk Road Saju','비단길 사주','Saju in Spanish, near Garosu-gil','{"en":"Saju in Spanish, near Garosu-gil","ko":"가로수길 근처, 스페인어 사주","zh":"新沙洞林荫道旁的西语四柱","ja":"カロスキル近く、スペイン語の四柱推命","es":"Saju en español, cerca de Garosu-gil"}'::jsonb,'One of the few places in Seoul offering Saju in Spanish without an interpreter. A calm room above a café, two minutes from Garosu-gil.','{"en":"One of the few places in Seoul offering Saju in Spanish without an interpreter. A calm room above a café, two minutes from Garosu-gil.","ko":"통역 없이 스페인어로 사주를 볼 수 있는 서울의 몇 안 되는 곳입니다. 가로수길에서 2분 거리 카페 위층의 차분한 방입니다.","zh":"首尔少数可以不用口译、直接用西班牙语看四柱的地方之一。位于咖啡馆楼上的安静房间，距林荫道两分钟。","ja":"ソウルでは数少ない、通訳なしのスペイン語で四柱推命が受けられる場所。カロスキルから2分、カフェの上の落ち着いた部屋です。","es":"Uno de los pocos lugares de Seúl con Saju en español sin intérprete. Una sala tranquila sobre una cafetería, a dos minutos de Garosu-gil."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Garosu-gil, Gangnam-gu','Seoul','Gangnam-gu','Sinsa',37.51841,127.023856,'Sinsa',5,35000,'KRW',30,1,0,array['general','love','wealth']::text[],array['saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('yeonnam-garden-gwansang','Garden Gwansang','정원 관상소','Traditional face reading in a garden room','{"en":"Traditional face reading in a garden room","ko":"정원이 보이는 방에서 보는 전통 관상","zh":"在花园房里看传统面相","ja":"庭の見える部屋で伝統の観相","es":"Lectura tradicional del rostro en una sala con jardín"}'::jsonb,'A ground-floor room opening onto a small garden off Yeonnam’s main strip. Face reading takes 30 minutes and needs no birth details, which makes it an easy add-on for groups.','{"en":"A ground-floor room opening onto a small garden off Yeonnam’s main strip. Face reading takes 30 minutes and needs no birth details, which makes it an easy add-on for groups.","ko":"연남동 큰길에서 조금 들어간, 작은 정원으로 이어지는 1층 방입니다. 관상은 30분이면 되고 생년월일이 필요 없어 일행과 함께 보기 좋습니다.","zh":"在延南洞主街旁、通往小花园的一楼房间。面相只需30分钟且无需出生信息，结伴来很方便加上。","ja":"延南洞の大通りから少し入った、小さな庭に面した1階の部屋。観相は30分で生年月日も不要なので、グループで気軽に追加できます。","es":"Una sala a pie de calle que da a un pequeño jardín junto a la calle principal de Yeonnam. La lectura del rostro dura 30 minutos y no necesita fecha de nacimiento, ideal como extra en grupo."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Donggyo-ro, Mapo-gu','Seoul','Mapo-gu','Yeonnam-dong',37.560521,126.923266,'Hongik Univ.',9,25000,'KRW',30,1,0,array['general','love']::text[],array['face_reading','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('dongdaemun-night-market-tarot','Night Market Tarot','야시장 타로','Late tarot by the fashion malls','{"en":"Late tarot by the fashion malls","ko":"패션몰 옆 심야 타로","zh":"时装商场旁的深夜塔罗","ja":"ファッションビル横の深夜タロット","es":"Tarot nocturno junto a los centros de moda"}'::jsonb,'A booth-sized studio by the Dongdaemun fashion malls, open until 11 pm. Quick, inexpensive tarot; add Saju if your question is about timing.','{"en":"A booth-sized studio by the Dongdaemun fashion malls, open until 11 pm. Quick, inexpensive tarot; add Saju if your question is about timing.","ko":"동대문 패션몰 옆 작은 부스 크기의 스튜디오로 밤 11시까지 엽니다. 빠르고 저렴한 타로에, 시기가 궁금하면 사주를 더하세요.","zh":"东大门时装商场旁一间小摊位大小的工作室，营业到晚上11点。快速又便宜的塔罗；问题和时机有关可加四柱。","ja":"東大門のファッションビル横にあるブースほどの小さなスタジオで、夜11時まで営業。手早く手頃なタロットに、時期が気になるなら四柱推命を追加。","es":"Un estudio del tamaño de un puesto junto a los centros de moda de Dongdaemun, abierto hasta las 23 h. Tarot rápido y barato; añade Saju si tu pregunta va de momentos."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Jangchungdan-ro, Jung-gu','Seoul','Jung-gu','Dongdaemun',37.56509,127.01016,'Dongdaemun History & Culture Park',3,25000,'KRW',30,1,0,array['love','general']::text[],array['tarot','saju']::text[],true,false,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('seochon-quiet-pine','Quiet Pine Saju','고요한 소나무 사주','A calm reading, summarised in a letter','{"en":"A calm reading, summarised in a letter","ko":"차분한 상담과 한 장의 편지","zh":"安静的解读，附一封总结信","ja":"落ち着いた鑑定と、まとめの手紙","es":"Una lectura tranquila, resumida en una carta"}'::jsonb,'A quiet studio on a Seochon backstreet near Tongin Market. After each reading the reader writes a one-page letter summarising what she saw.','{"en":"A quiet studio on a Seochon backstreet near Tongin Market. After each reading the reader writes a one-page letter summarising what she saw.","ko":"통인시장 근처 서촌 뒷골목의 조용한 스튜디오입니다. 상담이 끝나면 본 내용을 한 장의 편지로 정리해 드립니다.","zh":"通仁市场附近西村小巷里一间安静的工作室。每次解读后，老师会写一页信总结她看到的内容。","ja":"通仁市場近く、西村の裏通りにある静かなスタジオ。鑑定のあと、見えたことを1枚の手紙にまとめてくれます。","es":"Un estudio tranquilo en una callejuela de Seochon cerca del mercado de Tongin. Tras cada lectura, la lectora escribe una carta de una página con lo que vio."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Jahamun-ro, Jongno-gu','Seoul','Jongno-gu','Seochon',37.577744,126.971373,'Gyeongbokgung',7,50000,'KRW',45,1,0,array['traditional_saju','year_ahead','love']::text[],array['saju']::text[],true,false,false,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('jamsil-tower-view-tarot','Tower View Tarot','타워뷰 타로','Couple tarot with a tower view','{"en":"Couple tarot with a tower view","ko":"타워가 보이는 커플 타로","zh":"看得见塔景的情侣塔罗","ja":"タワーが見えるカップルタロット","es":"Tarot para parejas con vistas a la torre"}'::jsonb,'A step-free studio with a view of Lotte World Tower. Couples book the compatibility reading; solo guests usually come for a quick tarot spread.','{"en":"A step-free studio with a view of Lotte World Tower. Couples book the compatibility reading; solo guests usually come for a quick tarot spread.","ko":"롯데월드타워가 보이는 턱 없는 스튜디오입니다. 커플은 궁합을, 혼자 오신 분은 주로 가벼운 타로를 봅니다.","zh":"可以看到乐天世界塔的无障碍工作室。情侣多预约合盘，单人客人通常来抽一次塔罗。","ja":"ロッテワールドタワーが見える段差のないスタジオ。カップルは相性を、おひとりの方は手軽なタロットを受けることが多いです。","es":"Un estudio sin escalones con vistas a la Lotte World Tower. Las parejas reservan la compatibilidad; quien viene solo suele pedir una tirada rápida."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Olympic-ro, Songpa-gu','Seoul','Songpa-gu','Jamsil',37.508981,127.098937,'Jamsil',5,30000,'KRW',30,2,0,array['love','compatibility','general']::text[],array['tarot','saju','compatibility']::text[],true,true,true,false,null,null,null);
insert into public.saju_studios (slug,name,name_ko,tagline,tagline_i18n,description,description_i18n,status,is_mock,demo_chat_enabled,is_featured,verified,verification_note,address_line1,city,district,neighborhood,latitude,longitude,nearest_station,station_walk_minutes,base_price,currency,min_duration_minutes,max_guests,min_age,specialties,modalities,ai_interpretation_available,wheelchair_accessible,walk_ins,instant_book,phone,email,website) values ('ikseon-lantern-myeongri','Lantern Myeongri','등불 명리','Long readings with a former fortune columnist','{"en":"Long readings with a former fortune columnist","ko":"운세 칼럼니스트 출신 선생님의 깊은 상담","zh":"前运势专栏作家的深度解读","ja":"元・占いコラムニストによるじっくり鑑定","es":"Lecturas largas con un excolumnista del horóscopo"}'::jsonb,'A lantern-lit hanok room in Ikseon-dong. The master wrote a newspaper fortune column for years; an interpreter-reader joins to translate and take your follow-up questions.','{"en":"A lantern-lit hanok room in Ikseon-dong. The master wrote a newspaper fortune column for years; an interpreter-reader joins to translate and take your follow-up questions.","ko":"익선동의 등불이 켜진 한옥 방입니다. 선생님은 오래 신문 운세 칼럼을 썼고, 통역을 겸한 상담가가 함께해 통역과 추가 질문을 맡습니다.","zh":"益善洞一间点着灯笼的韩屋房间。老师写了多年报纸运势专栏；另有一位兼任口译的老师负责翻译和回答追问。","ja":"益善洞の灯りがともる韓屋の部屋。先生は長年新聞の占いコラムを書いてきました。通訳を兼ねた鑑定士が同席し、通訳と追加の質問を担当します。","es":"Una sala de hanok iluminada con farolillos en Ikseon-dong. El maestro escribió una columna de horóscopo durante años; una lectora intérprete traduce y atiende tus preguntas."}'::jsonb,'active',true,true,false,false,'Preview sample for trying SajuTeller. Not a real business.','Illustrative location · Supyo-ro 28-gil, Jongno-gu','Seoul','Jongno-gu','Ikseon-dong',37.570156,126.990519,'Jongno 3-ga',4,80000,'KRW',45,2,0,array['traditional_saju','career','compatibility']::text[],array['saju','compatibility']::text[],true,false,false,false,null,null,null);
insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='moon-gate-saju-insadong'),'Seo-yeon Park','박서연','Myeongri reader','Trained under a Jongno master for eight years and now explains charts in plain language, with a sketch of your four pillars to take home.','{"en":"Trained under a Jongno master for eight years and now explains charts in plain language, with a sketch of your four pillars to take home.","ko":"종로의 명리 선생님 밑에서 8년간 공부했고, 사주를 쉬운 말로 풀어 네 기둥을 그린 메모를 함께 드립니다."}'::jsonb,array['ko','en']::text[],array['general','traditional_saju','career','wealth']::text[],14,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='moon-gate-saju-insadong'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='moon-gate-saju-insadong') and display_name='Seo-yeon Park'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,35000,'KRW',1,true,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='moon-gate-saju-insadong'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='moon-gate-saju-insadong') and display_name='Seo-yeon Park'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,60000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='moon-gate-saju-insadong'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='moon-gate-saju-insadong') and display_name='Seo-yeon Park'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,55000,'KRW',1,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='moon-gate-saju-insadong'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='moon-gate-saju-insadong') and display_name='Seo-yeon Park'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,50000,'KRW',1,true,false,3,true);
