insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),'Ha-eun Jung','정하은','Tarot & Saju reader','Started reading cards for friends in university and opened her own lounge in 2019. Known for honest answers about love, delivered kindly.','{"en":"Started reading cards for friends in university and opened her own lounge in 2019. Known for honest answers about love, delivered kindly.","ko":"대학 시절 친구들에게 타로를 봐 주다 2019년에 직접 라운지를 열었습니다. 연애 고민에 솔직하지만 다정하게 답해 줍니다."}'::jsonb,array['ko','en']::text[],array['love','general']::text[],9,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae') and display_name='Ha-eun Jung'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,25000,'KRW',1,false,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae') and display_name='Ha-eun Jung'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,50000,'KRW',1,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae') and display_name='Ha-eun Jung'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,40000,'KRW',1,true,true,2,true);
