insert into public.studio_images (studio_id,image_url,alt_text,image_type,sort_order) values ((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),'https://images.unsplash.com/photo-1602523961358-f9f03dd557db?auto=format&fit=crop&w=1400&q=82','Candles on a dark wooden table','cover',0),((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),'https://images.unsplash.com/photo-1538485399081-7191377e8241?auto=format&fit=crop&w=1400&q=82','Neon signs in a Seoul alley','interior',1),((select id from public.saju_studios where slug='seoul-starlight-tarot-hongdae'),'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=1400&q=82','Green velvet sofa in a waiting area','interior',2);
insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='two-moons-atelier-seongsu'),'Daniel Yoon','윤대현','Compatibility reader','Grew up between Seoul and Vancouver and reads in Korean or English without an interpreter. Specialises in couples and close friends reading together.','{"en":"Grew up between Seoul and Vancouver and reads in Korean or English without an interpreter. Specialises in couples and close friends reading together.","ko":"서울과 밴쿠버를 오가며 자라 통역 없이 한국어와 영어로 상담합니다. 커플이나 가까운 친구가 함께 듣는 상담을 전문으로 합니다."}'::jsonb,array['ko','en']::text[],array['compatibility','love','marriage']::text[],11,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='two-moons-atelier-seongsu'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='two-moons-atelier-seongsu') and display_name='Daniel Yoon'),'compatibility','Couple Compatibility (2 guests)','{"en":"Couple Compatibility (2 guests)","ko":"커플 궁합 (2인)","zh":"情侣合盘（2人）","ja":"カップル相性（2名）","es":"Compatibilidad de pareja (2 personas)"}'::jsonb,'Both charts side by side: where you balance each other, likely friction points and the timing you share.','{"en":"Both charts side by side: where you balance each other, likely friction points and the timing you share.","ko":"두 사람의 사주를 나란히 놓고 서로 채워 주는 부분, 부딪히기 쉬운 부분, 함께하는 시기를 봐 드립니다.","zh":"双方命盘并列解读：互补之处、可能的摩擦，以及共同的时机。","ja":"おふたりの命式を並べ、補い合う点、ぶつかりやすい点、共通の時期を読みます。","es":"Las dos cartas lado a lado: dónde os equilibráis, posibles roces y los momentos que compartís."}'::jsonb,75,145000,'KRW',2,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='two-moons-atelier-seongsu'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='two-moons-atelier-seongsu') and display_name='Daniel Yoon'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,90000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='two-moons-atelier-seongsu'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='two-moons-atelier-seongsu') and display_name='Daniel Yoon'),'general','Friends Group Reading (up to 4)','{"en":"Friends Group Reading (up to 4)","ko":"친구 단체 상담 (최대 4인)","zh":"好友团体解读（最多4人）","ja":"友だちグループ（最大4名）","es":"Lectura en grupo de amigos (hasta 4)"}'::jsonb,'A relaxed shared session: each person’s day master and how the elements in your group mix.','{"en":"A relaxed shared session: each person’s day master and how the elements in your group mix.","ko":"함께 듣는 편안한 상담. 한 사람씩 일간을 보고, 일행의 오행이 어떻게 어우러지는지 풀어 드립니다.","zh":"轻松的共享解读：每个人的日主，以及大家五行如何搭配。","ja":"みんなで聞く気軽なセッション。一人ずつの日主と、グループ内の五行の相性を読みます。","es":"Una sesión compartida y relajada: el maestro del día de cada uno y cómo se mezclan los elementos del grupo."}'::jsonb,90,190000,'KRW',4,true,false,2,true);
