insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon'),'Kim Jong-hwan','김종환','Senior myeongri master','Has read charts in Bukchon for over thirty years. Slow and thorough; expect him to ask about your family and your work before he says anything about the future.','{"en":"Has read charts in Bukchon for over thirty years. Slow and thorough; expect him to ask about your family and your work before he says anything about the future.","ko":"30년 넘게 북촌에서 사주를 봐 왔습니다. 천천히 꼼꼼하게 보는 편이라 앞날을 말하기 전에 가족과 일에 대해 먼저 묻습니다."}'::jsonb,array['ko']::text[],array['traditional_saju','general','timing']::text[],32,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon') and display_name='Kim Jong-hwan'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,95000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon') and display_name='Kim Jong-hwan'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,80000,'KRW',1,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hanji-lamp-myeongri-bukchon') and display_name='Kim Jong-hwan'),'name_creation','Korean Name Creation','{"en":"Korean Name Creation","ko":"한국 이름 짓기","zh":"韩文名字创作","ja":"韓国名づけ","es":"Creación de nombre coreano"}'::jsonb,'A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.','{"en":"A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.","ko":"오행의 균형에 맞춘 한국 이름을 지어 드리고, 한자 뜻을 기념 카드에 적어 드립니다.","zh":"根据五行平衡为您取韩文名字，并把汉字含义写在纪念卡上。","ja":"五行のバランスに合わせた韓国名を考え、漢字の意味を記念カードに書いてお渡しします。","es":"Un nombre coreano elegido para equilibrar tus elementos, con el significado de los hanja en una tarjeta de recuerdo."}'::jsonb,60,110000,'KRW',1,true,true,2,true);
