insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='cloud-tea-saju-samcheong'),'Lee Mi-kyung','이미경','Saju reader & tea host','Ran a tea house for a decade before turning to myeongri. Serves a tea matched to your strongest element and reads while it steeps.','{"en":"Ran a tea house for a decade before turning to myeongri. Serves a tea matched to your strongest element and reads while it steeps.","ko":"10년간 찻집을 운영하다 명리를 공부했습니다. 가장 강한 오행에 맞춘 차를 내리고, 차가 우러나는 동안 사주를 풀어 줍니다."}'::jsonb,array['ko','ja']::text[],array['general','love','traditional_saju']::text[],12,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='cloud-tea-saju-samcheong'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='cloud-tea-saju-samcheong') and display_name='Lee Mi-kyung'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,35000,'KRW',1,true,false,0,true);
