insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='ikseon-fortune-room'),'Choi Yoon-ah','최윤아','Saju & face reader','Reads in a hanok alley café space and keeps sessions short and practical. Good for a first try between lunch and shopping.','{"en":"Reads in a hanok alley café space and keeps sessions short and practical. Good for a first try between lunch and shopping.","ko":"한옥 골목의 카페 공간에서 짧고 실용적으로 상담합니다. 점심과 쇼핑 사이에 처음 경험해 보기 좋습니다."}'::jsonb,array['ko','en']::text[],array['general','love']::text[],6,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-fortune-room'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-fortune-room') and display_name='Choi Yoon-ah'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,25000,'KRW',1,true,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-fortune-room'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-fortune-room') and display_name='Choi Yoon-ah'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,40000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-fortune-room'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-fortune-room') and display_name='Choi Yoon-ah'),'general','Face Reading (Gwansang)','{"en":"Face Reading (Gwansang)","ko":"관상","zh":"面相（观相）","ja":"観相（顔相占い）","es":"Lectura del rostro (gwansang)"}'::jsonb,'Traditional Korean face reading: what your features are said to show about temperament and fortune.','{"en":"Traditional Korean face reading: what your features are said to show about temperament and fortune.","ko":"얼굴의 생김새로 성향과 운의 흐름을 보는 전통 관상입니다.","zh":"韩国传统面相：从五官看性格与运势。","ja":"顔立ちから気質や運勢を読む、韓国伝統の観相です。","es":"Lectura tradicional coreana del rostro: lo que tus rasgos dirían de tu carácter y tu suerte."}'::jsonb,30,25000,'KRW',1,false,false,2,true);
