insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='seochon-ink-and-pillars'),'Han Ji-ho','한지호','Myeongri reader & calligrapher','A former graphic designer who now writes your four pillars in brush calligraphy as part of the reading. Fluent English after years working in London.','{"en":"A former graphic designer who now writes your four pillars in brush calligraphy as part of the reading. Fluent English after years working in London.","ko":"그래픽 디자이너 출신으로, 상담 중에 네 기둥을 붓글씨로 써 드립니다. 런던에서 오래 일해 영어가 능숙합니다."}'::jsonb,array['ko','en']::text[],array['career','traditional_saju','study']::text[],8,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-ink-and-pillars'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-ink-and-pillars') and display_name='Han Ji-ho'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,60000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-ink-and-pillars'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-ink-and-pillars') and display_name='Han Ji-ho'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,55000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-ink-and-pillars'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-ink-and-pillars') and display_name='Han Ji-ho'),'name_creation','Korean Name Creation','{"en":"Korean Name Creation","ko":"한국 이름 짓기","zh":"韩文名字创作","ja":"韓国名づけ","es":"Creación de nombre coreano"}'::jsonb,'A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.','{"en":"A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.","ko":"오행의 균형에 맞춘 한국 이름을 지어 드리고, 한자 뜻을 기념 카드에 적어 드립니다.","zh":"根据五行平衡为您取韩文名字，并把汉字含义写在纪念卡上。","ja":"五行のバランスに合わせた韓国名を考え、漢字の意味を記念カードに書いてお渡しします。","es":"Un nombre coreano elegido para equilibrar tus elementos, con el significado de los hanja en una tarjeta de recuerdo."}'::jsonb,60,70000,'KRW',1,true,true,2,true);
