insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='myeongdong-golden-hour-saju'),'Oh Sang-min','오상민','Saju reader','Covers the weekday afternoon shift and focuses on love and year-ahead readings.','{"en":"Covers the weekday afternoon shift and focuses on love and year-ahead readings.","ko":"평일 오후를 맡고 있으며 연애운과 신년운세를 주로 봅니다."}'::jsonb,array['ko']::text[],array['general','wealth','love']::text[],7,false,true,false,1);
