insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-golden-hour-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-golden-hour-saju') and display_name='Zhang Li-na'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,60000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-golden-hour-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-golden-hour-saju') and display_name='Zhang Li-na'),'wealth','Money Flow & Timing','{"en":"Money Flow & Timing","ko":"재물운 상담","zh":"财运与时机","ja":"金運リーディング","es":"Flujo de dinero y momentos"}'::jsonb,'How money tends to move through your chart, good years to save or invest, and habits worth watching.','{"en":"How money tends to move through your chart, good years to save or invest, and habits worth watching.","ko":"재물이 들어오고 나가는 흐름, 모으거나 투자하기 좋은 해, 주의할 습관을 짚어 드립니다.","zh":"命盘中的财富流向、适合储蓄或投资的年份，以及需要留意的习惯。","ja":"お金の流れ方、貯蓄や投資に向く年、気をつけたい習慣を読みます。","es":"Cómo se mueve el dinero en tu carta, buenos años para ahorrar o invertir y hábitos a vigilar."}'::jsonb,45,50000,'KRW',1,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-golden-hour-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-golden-hour-saju') and display_name='Oh Sang-min'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,3,true);
