insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='euljiro-neon-oracle'),'Bae Seung-jun','배승준','Tarot reader','A former bartender who reads tarot in a retro printing-alley space. Direct, funny, and good with career questions.','{"en":"A former bartender who reads tarot in a retro printing-alley space. Direct, funny, and good with career questions.","ko":"바텐더 출신으로, 레트로한 인쇄 골목의 공간에서 타로를 봅니다. 솔직하고 유쾌하며 진로 고민에 강합니다."}'::jsonb,array['ko','en']::text[],array['general','career','love']::text[],5,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='euljiro-neon-oracle'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='euljiro-neon-oracle') and display_name='Bae Seung-jun'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,25000,'KRW',1,false,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='euljiro-neon-oracle'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='euljiro-neon-oracle') and display_name='Bae Seung-jun'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,25000,'KRW',1,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='euljiro-neon-oracle'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='euljiro-neon-oracle') and display_name='Bae Seung-jun'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,50000,'KRW',1,true,false,2,true);
