insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='yeonnam-paper-moon'),'Grace Kang','강은혜','Saju & tarot reader','Korean-American, raised in LA, moved back to Seoul in 2018. Reads in English or Korean and is great with groups of friends.','{"en":"Korean-American, raised in LA, moved back to Seoul in 2018. Reads in English or Korean and is great with groups of friends.","ko":"LA에서 자란 재미교포로 2018년에 서울로 돌아왔습니다. 영어와 한국어로 상담하며 친구들끼리 오는 단체 상담에 강합니다."}'::jsonb,array['en','ko']::text[],array['love','general','compatibility']::text[],7,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='yeonnam-paper-moon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='yeonnam-paper-moon') and display_name='Grace Kang'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,65000,'KRW',1,true,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='yeonnam-paper-moon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='yeonnam-paper-moon') and display_name='Grace Kang'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='yeonnam-paper-moon'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='yeonnam-paper-moon') and display_name='Grace Kang'),'general','Friends Group Reading (up to 4)','{"en":"Friends Group Reading (up to 4)","ko":"친구 단체 상담 (최대 4인)","zh":"好友团体解读（最多4人）","ja":"友だちグループ（最大4名）","es":"Lectura en grupo de amigos (hasta 4)"}'::jsonb,'A relaxed shared session: each person’s day master and how the elements in your group mix.','{"en":"A relaxed shared session: each person’s day master and how the elements in your group mix.","ko":"함께 듣는 편안한 상담. 한 사람씩 일간을 보고, 일행의 오행이 어떻게 어우러지는지 풀어 드립니다.","zh":"轻松的共享解读：每个人的日主，以及大家五行如何搭配。","ja":"みんなで聞く気軽なセッション。一人ずつの日主と、グループ内の五行の相性を読みます。","es":"Una sesión compartida y relajada: el maestro del día de cada uno y cómo se mezclan los elementos del grupo."}'::jsonb,90,120000,'KRW',4,true,false,2,true);
