insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='mangwon-riverside-saju'),'Song Min-ji','송민지','Saju reader','A local favourite near Mangwon Market. Warm and chatty; sessions often end with a recommendation for where to eat nearby.','{"en":"A local favourite near Mangwon Market. Warm and chatty; sessions often end with a recommendation for where to eat nearby.","ko":"망원시장 근처에서 동네 사람들이 즐겨 찾는 선생님입니다. 다정하고 이야기를 좋아해서 상담이 끝나면 근처 맛집을 추천해 주기도 합니다."}'::jsonb,array['ko']::text[],array['general','love','year_ahead']::text[],9,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='mangwon-riverside-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='mangwon-riverside-saju') and display_name='Song Min-ji'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,25000,'KRW',1,true,false,0,true);
