insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='sinchon-campus-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='sinchon-campus-tarot') and display_name='Kwon Da-hye'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,25000,'KRW',1,false,false,0,true);
