insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='itaewon-crossroads-readings'),'Sofia Lim','임소피아','Saju & tarot reader','Half Korean, half Mexican, raised in Guadalajara and Seoul. Reads in English, Spanish or Korean, often for people deciding whether to move abroad.','{"en":"Half Korean, half Mexican, raised in Guadalajara and Seoul. Reads in English, Spanish or Korean, often for people deciding whether to move abroad.","ko":"한국과 멕시코 혼혈로 과달라하라와 서울에서 자랐습니다. 영어, 스페인어, 한국어로 상담하며 해외 이주를 고민하는 분들이 많이 찾습니다."}'::jsonb,array['en','es','ko']::text[],array['career','relocation','love']::text[],8,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='itaewon-crossroads-readings'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='itaewon-crossroads-readings') and display_name='Sofia Lim'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,65000,'KRW',1,true,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='itaewon-crossroads-readings'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='itaewon-crossroads-readings') and display_name='Sofia Lim'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,55000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='itaewon-crossroads-readings'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='itaewon-crossroads-readings') and display_name='Sofia Lim'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,2,true);
