insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='hannam-quiet-hour'),'Jeon Hye-won','전혜원','Myeongri consultant','Spent twelve years in corporate finance before training in myeongri. Now reads mainly for founders and executives facing timing decisions.','{"en":"Spent twelve years in corporate finance before training in myeongri. Now reads mainly for founders and executives facing timing decisions.","ko":"기업 재무 분야에서 12년을 일한 뒤 명리를 공부했습니다. 지금은 주로 중요한 시기를 앞둔 창업자와 임원의 사주를 봅니다."}'::jsonb,array['ko','en']::text[],array['career','wealth','timing','business']::text[],13,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hannam-quiet-hour'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hannam-quiet-hour') and display_name='Jeon Hye-won'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,95000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hannam-quiet-hour'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hannam-quiet-hour') and display_name='Jeon Hye-won'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,90000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hannam-quiet-hour'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hannam-quiet-hour') and display_name='Jeon Hye-won'),'wealth','Money Flow & Timing','{"en":"Money Flow & Timing","ko":"재물운 상담","zh":"财运与时机","ja":"金運リーディング","es":"Flujo de dinero y momentos"}'::jsonb,'How money tends to move through your chart, good years to save or invest, and habits worth watching.','{"en":"How money tends to move through your chart, good years to save or invest, and habits worth watching.","ko":"재물이 들어오고 나가는 흐름, 모으거나 투자하기 좋은 해, 주의할 습관을 짚어 드립니다.","zh":"命盘中的财富流向、适合储蓄或投资的年份，以及需要留意的习惯。","ja":"お金の流れ方、貯蓄や投資に向く年、気をつけたい習慣を読みます。","es":"Cómo se mueve el dinero en tu carta, buenos años para ahorrar o invertir y hábitos a vigilar."}'::jsonb,45,80000,'KRW',1,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hannam-quiet-hour'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hannam-quiet-hour') and display_name='Jeon Hye-won'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,80000,'KRW',1,true,false,3,true);
