insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),'Shin Dong-hoon','신동훈','Senior myeongri master','Twenty-five years of practice and a long waiting list among Gangnam office workers. Precise about dates and direct about what he sees.','{"en":"Twenty-five years of practice and a long waiting list among Gangnam office workers. Precise about dates and direct about what he sees.","ko":"25년 경력으로 강남 직장인들 사이에 대기가 긴 선생님입니다. 날짜를 정확하게 짚고 보이는 대로 솔직하게 말합니다."}'::jsonb,array['ko']::text[],array['career','wealth','compatibility','business']::text[],25,true,true,false,0);
insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),'Yoon Ji-su','윤지수','Compatibility reader','Handles couple and family readings, and sits in as a second reader for longer sessions.','{"en":"Handles couple and family readings, and sits in as a second reader for longer sessions.","ko":"커플과 가족 궁합을 맡고, 긴 상담에는 두 번째 상담가로 함께합니다."}'::jsonb,array['ko','en']::text[],array['career','wealth','compatibility','business']::text[],9,false,true,false,1);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='gangnam-compass-myeongri') and display_name='Shin Dong-hoon'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,95000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='gangnam-compass-myeongri') and display_name='Shin Dong-hoon'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,90000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='gangnam-compass-myeongri') and display_name='Shin Dong-hoon'),'wealth','Money Flow & Timing','{"en":"Money Flow & Timing","ko":"재물운 상담","zh":"财运与时机","ja":"金運リーディング","es":"Flujo de dinero y momentos"}'::jsonb,'How money tends to move through your chart, good years to save or invest, and habits worth watching.','{"en":"How money tends to move through your chart, good years to save or invest, and habits worth watching.","ko":"재물이 들어오고 나가는 흐름, 모으거나 투자하기 좋은 해, 주의할 습관을 짚어 드립니다.","zh":"命盘中的财富流向、适合储蓄或投资的年份，以及需要留意的习惯。","ja":"お金の流れ方、貯蓄や投資に向く年、気をつけたい習慣を読みます。","es":"Cómo se mueve el dinero en tu carta, buenos años para ahorrar o invertir y hábitos a vigilar."}'::jsonb,45,80000,'KRW',1,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='gangnam-compass-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='gangnam-compass-myeongri') and display_name='Yoon Ji-su'),'compatibility','Couple Compatibility (2 guests)','{"en":"Couple Compatibility (2 guests)","ko":"커플 궁합 (2인)","zh":"情侣合盘（2人）","ja":"カップル相性（2名）","es":"Compatibilidad de pareja (2 personas)"}'::jsonb,'Both charts side by side: where you balance each other, likely friction points and the timing you share.','{"en":"Both charts side by side: where you balance each other, likely friction points and the timing you share.","ko":"두 사람의 사주를 나란히 놓고 서로 채워 주는 부분, 부딪히기 쉬운 부분, 함께하는 시기를 봐 드립니다.","zh":"双方命盘并列解读：互补之处、可能的摩擦，以及共同的时机。","ja":"おふたりの命式を並べ、補い合う点、ぶつかりやすい点、共通の時期を読みます。","es":"Las dos cartas lado a lado: dónde os equilibráis, posibles roces y los momentos que compartís."}'::jsonb,75,145000,'KRW',2,true,true,3,true);
