insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='garosu-gil-blossom-tarot'),'Aoi Morita','모리타 아오이','Tarot reader','Moved from Osaka to Seoul in 2016. Reads tarot in Japanese or Korean and is a favourite with visitors from Japan.','{"en":"Moved from Osaka to Seoul in 2016. Reads tarot in Japanese or Korean and is a favourite with visitors from Japan.","ko":"2016년 오사카에서 서울로 왔습니다. 일본어와 한국어로 타로를 보며 일본에서 온 방문객에게 특히 인기가 많습니다."}'::jsonb,array['ja','ko']::text[],array['love','compatibility','general']::text[],10,true,true,false,0);
insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='garosu-gil-blossom-tarot'),'Jang Se-ra','장세라','Saju reader','Adds the Saju side for combo sessions and couple readings.','{"en":"Adds the Saju side for combo sessions and couple readings.","ko":"콤보 상담과 커플 궁합에서 사주를 맡습니다."}'::jsonb,array['ko','en']::text[],array['love','compatibility','general']::text[],6,false,true,false,1);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='garosu-gil-blossom-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='garosu-gil-blossom-tarot') and display_name='Aoi Morita'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,30000,'KRW',1,false,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='garosu-gil-blossom-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='garosu-gil-blossom-tarot') and display_name='Aoi Morita'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,65000,'KRW',1,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='garosu-gil-blossom-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='garosu-gil-blossom-tarot') and display_name='Aoi Morita'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,2,true);
