insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='jamsil-lakeside-fortune'),'Hwang Bo-ram','황보람','Saju reader','Patient and clear, with a lot of practice explaining Saju to families and first-time visitors.','{"en":"Patient and clear, with a lot of practice explaining Saju to families and first-time visitors.","ko":"차분하고 명확하게 설명하며, 가족 단위나 처음 오신 분께 사주를 풀어 드린 경험이 많습니다."}'::jsonb,array['ko','en']::text[],array['general','year_ahead','career']::text[],11,true,true,false,0);
