insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='jamsil-lakeside-fortune'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='jamsil-lakeside-fortune') and display_name='Hwang Bo-ram'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,50000,'KRW',1,true,false,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='jamsil-lakeside-fortune'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='jamsil-lakeside-fortune') and display_name='Hwang Bo-ram'),'general','Friends Group Reading (up to 4)','{"en":"Friends Group Reading (up to 4)","ko":"친구 단체 상담 (최대 4인)","zh":"好友团体解读（最多4人）","ja":"友だちグループ（最大4名）","es":"Lectura en grupo de amigos (hasta 4)"}'::jsonb,'A relaxed shared session: each person’s day master and how the elements in your group mix.','{"en":"A relaxed shared session: each person’s day master and how the elements in your group mix.","ko":"함께 듣는 편안한 상담. 한 사람씩 일간을 보고, 일행의 오행이 어떻게 어우러지는지 풀어 드립니다.","zh":"轻松的共享解读：每个人的日主，以及大家五行如何搭配。","ja":"みんなで聞く気軽なセッション。一人ずつの日主と、グループ内の五行の相性を読みます。","es":"Una sesión compartida y relajada: el maestro del día de cada uno y cómo se mezclan los elementos del grupo."}'::jsonb,90,120000,'KRW',4,true,false,3,true);
