insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='yeouido-market-hours-saju'),'Ko Seung-woo','고승우','Career & wealth reader','Works a block from the financial district and reads for a lot of bankers and analysts over lunch breaks.','{"en":"Works a block from the financial district and reads for a lot of bankers and analysts over lunch breaks.","ko":"금융가에서 한 블록 떨어진 곳에서 점심시간에 은행원과 애널리스트의 사주를 많이 봅니다."}'::jsonb,array['ko','en']::text[],array['career','wealth','business']::text[],15,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='yeouido-market-hours-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='yeouido-market-hours-saju') and display_name='Ko Seung-woo'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,55000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='yeouido-market-hours-saju'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='yeouido-market-hours-saju') and display_name='Ko Seung-woo'),'wealth','Money Flow & Timing','{"en":"Money Flow & Timing","ko":"재물운 상담","zh":"财运与时机","ja":"金運リーディング","es":"Flujo de dinero y momentos"}'::jsonb,'How money tends to move through your chart, good years to save or invest, and habits worth watching.','{"en":"How money tends to move through your chart, good years to save or invest, and habits worth watching.","ko":"재물이 들어오고 나가는 흐름, 모으거나 투자하기 좋은 해, 주의할 습관을 짚어 드립니다.","zh":"命盘中的财富流向、适合储蓄或投资的年份，以及需要留意的习惯。","ja":"お金の流れ方、貯蓄や投資に向く年、気をつけたい習慣を読みます。","es":"Cómo se mueve el dinero en tu carta, buenos años para ahorrar o invertir y hábitos a vigilar."}'::jsonb,45,50000,'KRW',1,true,true,1,true);
