insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='insadong-old-almanac'),'Jo Byung-chul','조병철','Saju & face reader','A retired schoolteacher who reads from his collection of old almanacs and enjoys explaining the history behind each term.','{"en":"A retired schoolteacher who reads from his collection of old almanacs and enjoys explaining the history behind each term.","ko":"은퇴한 교사로, 모아 온 옛 책력을 펼쳐 놓고 상담하며 용어마다 담긴 역사를 설명하길 좋아합니다."}'::jsonb,array['ko']::text[],array['traditional_saju','general']::text[],18,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='insadong-old-almanac'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='insadong-old-almanac') and display_name='Jo Byung-chul'),'general','First Saju Reading','{"en":"First Saju Reading","ko":"첫 사주 상담","zh":"初次四柱体验","ja":"はじめての四柱推命","es":"Primera lectura de Saju"}'::jsonb,'A short introduction for first-timers: your day master, your element balance and one question of your choice.','{"en":"A short introduction for first-timers: your day master, your element balance and one question of your choice.","ko":"처음 오신 분을 위한 짧은 상담. 일간과 오행의 균형, 그리고 원하는 질문 하나를 봐 드립니다.","zh":"为初次体验者准备的简短解读：日主、五行平衡，以及您想问的一个问题。","ja":"初めての方向けの短いセッション。日主と五行のバランス、気になる質問をひとつ読みます。","es":"Una introducción breve: tu maestro del día, el equilibrio de tus elementos y una pregunta a tu elección."}'::jsonb,30,25000,'KRW',1,true,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='insadong-old-almanac'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='insadong-old-almanac') and display_name='Jo Byung-chul'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,45000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='insadong-old-almanac'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='insadong-old-almanac') and display_name='Jo Byung-chul'),'general','Face Reading (Gwansang)','{"en":"Face Reading (Gwansang)","ko":"관상","zh":"面相（观相）","ja":"観相（顔相占い）","es":"Lectura del rostro (gwansang)"}'::jsonb,'Traditional Korean face reading: what your features are said to show about temperament and fortune.','{"en":"Traditional Korean face reading: what your features are said to show about temperament and fortune.","ko":"얼굴의 생김새로 성향과 운의 흐름을 보는 전통 관상입니다.","zh":"韩国传统面相：从五官看性格与运势。","ja":"顔立ちから気質や運勢を読む、韓国伝統の観相です。","es":"Lectura tradicional coreana del rostro: lo que tus rasgos dirían de tu carácter y tu suerte."}'::jsonb,30,25000,'KRW',1,false,false,2,true);
