insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='bukchon-morning-bell'),'Lim Eun-sook','임은숙','Saju reader','Reads in a small hanok guesthouse she runs with her husband; many guests book a reading the morning after they stay.','{"en":"Reads in a small hanok guesthouse she runs with her husband; many guests book a reading the morning after they stay.","ko":"남편과 운영하는 작은 한옥 게스트하우스에서 상담합니다. 묵고 난 다음 날 아침에 상담을 예약하는 손님이 많습니다."}'::jsonb,array['ko']::text[],array['general','love','year_ahead']::text[],16,true,true,false,0);
