insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='hongdae-cosmic-diner'),'Yang Jun-young','양준영','Tarot reader','Hosts friend groups in a retro diner-style room and keeps things light, but takes the question seriously.','{"en":"Hosts friend groups in a retro diner-style room and keeps things light, but takes the question seriously.","ko":"레트로 다이너 분위기의 방에서 친구 모임을 맞이합니다. 분위기는 가볍게, 질문은 진지하게 다룹니다."}'::jsonb,array['ko','en','ja']::text[],array['love','general','compatibility']::text[],4,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hongdae-cosmic-diner'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hongdae-cosmic-diner') and display_name='Yang Jun-young'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,25000,'KRW',1,false,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hongdae-cosmic-diner'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hongdae-cosmic-diner') and display_name='Yang Jun-young'),'general','Friends Group Reading (up to 4)','{"en":"Friends Group Reading (up to 4)","ko":"친구 단체 상담 (최대 4인)","zh":"好友团体解读（最多4人）","ja":"友だちグループ（最大4名）","es":"Lectura en grupo de amigos (hasta 4)"}'::jsonb,'A relaxed shared session: each person’s day master and how the elements in your group mix.','{"en":"A relaxed shared session: each person’s day master and how the elements in your group mix.","ko":"함께 듣는 편안한 상담. 한 사람씩 일간을 보고, 일행의 오행이 어떻게 어우러지는지 풀어 드립니다.","zh":"轻松的共享解读：每个人的日主，以及大家五行如何搭配。","ja":"みんなで聞く気軽なセッション。一人ずつの日主と、グループ内の五行の相性を読みます。","es":"Una sesión compartida y relajada: el maestro del día de cada uno y cómo se mezclan los elementos del grupo."}'::jsonb,90,90000,'KRW',4,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='hongdae-cosmic-diner'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='hongdae-cosmic-diner') and display_name='Yang Jun-young'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,50000,'KRW',1,true,false,2,true);
