insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='myeongdong-jade-pavilion'),'Wang Mei','왕메이','Myeongri master','From Taipei, has lived in Seoul for twenty years. Reads in Mandarin and Korean and is known for detailed wealth readings.','{"en":"From Taipei, has lived in Seoul for twenty years. Reads in Mandarin and Korean and is known for detailed wealth readings.","ko":"타이베이 출신으로 서울에서 20년째 살고 있습니다. 중국어와 한국어로 상담하며 자세한 재물운 풀이로 알려져 있습니다."}'::jsonb,array['zh','ko']::text[],array['wealth','compatibility','traditional_saju']::text[],20,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-jade-pavilion'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-jade-pavilion') and display_name='Wang Mei'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,95000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-jade-pavilion'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-jade-pavilion') and display_name='Wang Mei'),'wealth','Money Flow & Timing','{"en":"Money Flow & Timing","ko":"재물운 상담","zh":"财运与时机","ja":"金運リーディング","es":"Flujo de dinero y momentos"}'::jsonb,'How money tends to move through your chart, good years to save or invest, and habits worth watching.','{"en":"How money tends to move through your chart, good years to save or invest, and habits worth watching.","ko":"재물이 들어오고 나가는 흐름, 모으거나 투자하기 좋은 해, 주의할 습관을 짚어 드립니다.","zh":"命盘中的财富流向、适合储蓄或投资的年份，以及需要留意的习惯。","ja":"お金の流れ方、貯蓄や投資に向く年、気をつけたい習慣を読みます。","es":"Cómo se mueve el dinero en tu carta, buenos años para ahorrar o invertir y hábitos a vigilar."}'::jsonb,45,80000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-jade-pavilion'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-jade-pavilion') and display_name='Wang Mei'),'compatibility','Couple Compatibility (2 guests)','{"en":"Couple Compatibility (2 guests)","ko":"커플 궁합 (2인)","zh":"情侣合盘（2人）","ja":"カップル相性（2名）","es":"Compatibilidad de pareja (2 personas)"}'::jsonb,'Both charts side by side: where you balance each other, likely friction points and the timing you share.','{"en":"Both charts side by side: where you balance each other, likely friction points and the timing you share.","ko":"두 사람의 사주를 나란히 놓고 서로 채워 주는 부분, 부딪히기 쉬운 부분, 함께하는 시기를 봐 드립니다.","zh":"双方命盘并列解读：互补之处、可能的摩擦，以及共同的时机。","ja":"おふたりの命式を並べ、補い合う点、ぶつかりやすい点、共通の時期を読みます。","es":"Las dos cartas lado a lado: dónde os equilibráis, posibles roces y los momentos que compartís."}'::jsonb,75,145000,'KRW',2,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='myeongdong-jade-pavilion'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='myeongdong-jade-pavilion') and display_name='Wang Mei'),'name_creation','Korean Name Creation','{"en":"Korean Name Creation","ko":"한국 이름 짓기","zh":"韩文名字创作","ja":"韓国名づけ","es":"Creación de nombre coreano"}'::jsonb,'A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.','{"en":"A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.","ko":"오행의 균형에 맞춘 한국 이름을 지어 드리고, 한자 뜻을 기념 카드에 적어 드립니다.","zh":"根据五行平衡为您取韩文名字，并把汉字含义写在纪念卡上。","ja":"五行のバランスに合わせた韓国名を考え、漢字の意味を記念カードに書いてお渡しします。","es":"Un nombre coreano elegido para equilibrar tus elementos, con el significado de los hanja en una tarjeta de recuerdo."}'::jsonb,60,110000,'KRW',1,true,true,3,true);
