insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='euljiro-red-thread'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='euljiro-red-thread') and display_name='Seo Ye-jin'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,1,true);
