insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='samcheong-mountain-view'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='samcheong-mountain-view') and display_name='Park Chang-ho'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,90000,'KRW',1,true,true,2,true);
