insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='gangnam-blue-hour-saju'),'Cha Yeon-woo','차연우','Saju & tarot reader','Works the evening shift for people coming straight from the office. Clear, upbeat and good at turning a chart into next steps.','{"en":"Works the evening shift for people coming straight from the office. Clear, upbeat and good at turning a chart into next steps.","ko":"퇴근 후 바로 오는 분들을 위해 저녁 시간을 맡고 있습니다. 명쾌하고 밝으며 사주를 다음 행동으로 정리해 주는 데 능합니다."}'::jsonb,array['ko','en']::text[],array['love','career','general']::text[],6,true,true,false,0);
