insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='itaewon-hilltop-names'),'Ryu Ji-an','류지안','Naming specialist','Has chosen Korean names for hundreds of visitors and second-generation Koreans. Writes each name in hangul and hanja on a card.','{"en":"Has chosen Korean names for hundreds of visitors and second-generation Koreans. Writes each name in hangul and hanja on a card.","ko":"수백 명의 방문객과 해외 동포 2세에게 한국 이름을 지어 줬습니다. 이름마다 한글과 한자로 카드에 적어 드립니다."}'::jsonb,array['ko','en']::text[],array['general','traditional_saju']::text[],12,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='itaewon-hilltop-names'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='itaewon-hilltop-names') and display_name='Ryu Ji-an'),'name_creation','Korean Name Creation','{"en":"Korean Name Creation","ko":"한국 이름 짓기","zh":"韩文名字创作","ja":"韓国名づけ","es":"Creación de nombre coreano"}'::jsonb,'A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.','{"en":"A Korean name chosen to balance your elements, with the hanja meanings written out on a keepsake card.","ko":"오행의 균형에 맞춘 한국 이름을 지어 드리고, 한자 뜻을 기념 카드에 적어 드립니다.","zh":"根据五行平衡为您取韩文名字，并把汉字含义写在纪念卡上。","ja":"五行のバランスに合わせた韓国名を考え、漢字の意味を記念カードに書いてお渡しします。","es":"Un nombre coreano elegido para equilibrar tus elementos, con el significado de los hanja en una tarjeta de recuerdo."}'::jsonb,60,70000,'KRW',1,true,true,0,true);
