insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='itaewon-hilltop-names'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='itaewon-hilltop-names') and display_name='Ryu Ji-an'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,60000,'KRW',1,true,true,2,true);
