insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='dongdaemun-night-market-tarot'),'Ahn So-hee','안소희','Tarot reader','Reads late into the night for shoppers coming out of the fashion malls. Speaks some Mandarin.','{"en":"Reads late into the night for shoppers coming out of the fashion malls. Speaks some Mandarin.","ko":"패션몰에서 나오는 쇼핑객을 위해 밤늦게까지 타로를 봅니다. 중국어도 조금 합니다."}'::jsonb,array['ko','zh']::text[],array['love','general']::text[],5,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='dongdaemun-night-market-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='dongdaemun-night-market-tarot') and display_name='Ahn So-hee'),'tarot','Tarot Reading','{"en":"Tarot Reading","ko":"타로 상담","zh":"塔罗占卜","ja":"タロットリーディング","es":"Lectura de tarot"}'::jsonb,'A card spread around one question, with time to ask follow-ups. No birth details needed.','{"en":"A card spread around one question, with time to ask follow-ups. No birth details needed.","ko":"질문 하나를 두고 카드를 펼쳐 풀어 드리며, 추가 질문 시간도 있습니다. 생년월일은 필요 없습니다.","zh":"围绕一个问题展开牌阵，并留有追问时间。无需出生信息。","ja":"ひとつの質問についてカードを展開し、追加の質問も受け付けます。生年月日は不要です。","es":"Una tirada sobre una pregunta, con tiempo para repreguntar. No hace falta fecha de nacimiento."}'::jsonb,30,25000,'KRW',1,false,false,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='dongdaemun-night-market-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='dongdaemun-night-market-tarot') and display_name='Ahn So-hee'),'tarot','Saju + Tarot','{"en":"Saju + Tarot","ko":"사주 + 타로","zh":"四柱 + 塔罗","ja":"四柱推命 + タロット","es":"Saju + tarot"}'::jsonb,'Your Saju for the big picture, then a tarot spread for the question on your mind right now.','{"en":"Your Saju for the big picture, then a tarot spread for the question on your mind right now.","ko":"사주로 큰 흐름을 보고, 지금 고민하는 질문은 타로로 한 번 더 짚어 드립니다.","zh":"先用四柱看整体走势，再用塔罗解答您当下的问题。","ja":"四柱推命で大きな流れを見て、いまの悩みはタロットでもう一度読みます。","es":"Tu Saju para la visión general y una tirada de tarot para la pregunta que tienes ahora."}'::jsonb,60,50000,'KRW',1,true,false,1,true);
