insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='seochon-quiet-pine'),'Baek Seon-hwa','백선화','Saju reader','A soft-spoken reader who writes a short letter summarising your reading and posts a photo of it to you afterwards.','{"en":"A soft-spoken reader who writes a short letter summarising your reading and posts a photo of it to you afterwards.","ko":"조용조용 말하는 선생님으로, 상담 내용을 짧은 편지로 정리해 사진으로 보내 드립니다."}'::jsonb,array['ko']::text[],array['traditional_saju','year_ahead','love']::text[],13,true,true,false,0);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-quiet-pine'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-quiet-pine') and display_name='Baek Seon-hwa'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,60000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-quiet-pine'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-quiet-pine') and display_name='Baek Seon-hwa'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,50000,'KRW',1,true,false,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='seochon-quiet-pine'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='seochon-quiet-pine') and display_name='Baek Seon-hwa'),'love','Love & Relationship Reading','{"en":"Love & Relationship Reading","ko":"연애·결혼운 상담","zh":"感情与婚姻解读","ja":"恋愛・結婚運リーディング","es":"Lectura de amor y relaciones"}'::jsonb,'Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.','{"en":"Your patterns in relationships, the years that favour meeting someone or settling down, and what suits you in a partner.","ko":"연애 패턴과 인연이 들어오는 시기, 결혼운, 잘 맞는 상대의 성향을 봐 드립니다.","zh":"感情模式、适合遇见对象或成家的年份，以及适合您的伴侣类型。","ja":"恋愛の傾向、出会いや結婚に向く時期、相性の良い相手のタイプを読みます。","es":"Tus patrones en pareja, los años favorables para conocer a alguien o asentarte y qué te conviene en una pareja."}'::jsonb,50,55000,'KRW',1,true,true,2,true);
