insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='jamsil-tower-view-tarot'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='jamsil-tower-view-tarot') and display_name='Kang Min-seo'),'compatibility','Couple Compatibility (2 guests)','{"en":"Couple Compatibility (2 guests)","ko":"커플 궁합 (2인)","zh":"情侣合盘（2人）","ja":"カップル相性（2名）","es":"Compatibilidad de pareja (2 personas)"}'::jsonb,'Both charts side by side: where you balance each other, likely friction points and the timing you share.','{"en":"Both charts side by side: where you balance each other, likely friction points and the timing you share.","ko":"두 사람의 사주를 나란히 놓고 서로 채워 주는 부분, 부딪히기 쉬운 부분, 함께하는 시기를 봐 드립니다.","zh":"双方命盘并列解读：互补之处、可能的摩擦，以及共同的时机。","ja":"おふたりの命式を並べ、補い合う点、ぶつかりやすい点、共通の時期を読みます。","es":"Las dos cartas lado a lado: dónde os equilibráis, posibles roces y los momentos que compartís."}'::jsonb,75,90000,'KRW',2,true,true,1,true);
