insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),'Do Hyun-jae','도현재','Myeongri master','A former newspaper columnist who wrote the weekly fortune page for years. Precise, literary and often funny.','{"en":"A former newspaper columnist who wrote the weekly fortune page for years. Precise, literary and often funny.","ko":"오랫동안 신문의 주간 운세 칼럼을 쓴 칼럼니스트 출신입니다. 정확하고 문학적이며 유머도 있습니다."}'::jsonb,array['ko']::text[],array['traditional_saju','career','compatibility']::text[],22,true,true,false,0);
insert into public.studio_practitioners (studio_id,display_name,display_name_ko,title,bio,bio_i18n,languages,specialties,years_experience,is_primary,is_active,verified,sort_order) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),'Kim Na-rae','김나래','Interpreter & junior reader','Interprets for English-speaking guests and handles the follow-up questions.','{"en":"Interprets for English-speaking guests and handles the follow-up questions.","ko":"영어권 손님을 위해 통역하고 추가 질문을 맡습니다."}'::jsonb,array['ko','en']::text[],array['traditional_saju','career','compatibility']::text[],4,false,true,false,1);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-lantern-myeongri') and display_name='Do Hyun-jae'),'traditional_saju','Four Pillars Reading','{"en":"Four Pillars Reading","ko":"정통 사주 풀이","zh":"四柱八字详解","ja":"四柱推命フルリーディング","es":"Lectura de los Cuatro Pilares"}'::jsonb,'Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.','{"en":"Your chart laid out pillar by pillar: temperament, strengths, and the ten-year luck cycles ahead.","ko":"사주팔자를 기둥별로 풀어 성향과 강점, 앞으로의 대운 흐름을 짚어 드립니다.","zh":"逐柱解读命盘：性格、优势，以及未来的十年大运。","ja":"命式を柱ごとに読み解き、気質や強み、これからの大運の流れをお伝えします。","es":"Tu carta pilar por pilar: temperamento, fortalezas y los ciclos de suerte de diez años que vienen."}'::jsonb,60,95000,'KRW',1,true,true,0,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-lantern-myeongri') and display_name='Do Hyun-jae'),'career','Career & Direction Reading','{"en":"Career & Direction Reading","ko":"직업·진로운 상담","zh":"事业与方向解读","ja":"仕事・進路リーディング","es":"Lectura de carrera y rumbo"}'::jsonb,'Job changes, starting a business and which years favour a move, built around the decision you are facing.','{"en":"Job changes, starting a business and which years favour a move, built around the decision you are facing.","ko":"이직, 창업, 움직이기 좋은 해를 지금 고민 중인 결정에 맞춰 봐 드립니다.","zh":"围绕您正在面对的决定，解读跳槽、创业以及适合行动的年份。","ja":"転職や起業、動くのに良い年を、いま迷っている決断に沿って読みます。","es":"Cambios de trabajo, emprender y qué años favorecen un cambio, centrado en la decisión que tienes delante."}'::jsonb,50,90000,'KRW',1,true,true,1,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-lantern-myeongri') and display_name='Do Hyun-jae'),'compatibility','Couple Compatibility (2 guests)','{"en":"Couple Compatibility (2 guests)","ko":"커플 궁합 (2인)","zh":"情侣合盘（2人）","ja":"カップル相性（2名）","es":"Compatibilidad de pareja (2 personas)"}'::jsonb,'Both charts side by side: where you balance each other, likely friction points and the timing you share.','{"en":"Both charts side by side: where you balance each other, likely friction points and the timing you share.","ko":"두 사람의 사주를 나란히 놓고 서로 채워 주는 부분, 부딪히기 쉬운 부분, 함께하는 시기를 봐 드립니다.","zh":"双方命盘并列解读：互补之处、可能的摩擦，以及共同的时机。","ja":"おふたりの命式を並べ、補い合う点、ぶつかりやすい点、共通の時期を読みます。","es":"Las dos cartas lado a lado: dónde os equilibráis, posibles roces y los momentos que compartís."}'::jsonb,75,145000,'KRW',2,true,true,2,true);
insert into public.studio_services (studio_id,practitioner_id,service_type,name,name_i18n,description,description_i18n,duration_minutes,price,currency,max_guests,requires_birth_date,birth_time_recommended,sort_order,active) values ((select id from public.saju_studios where slug='ikseon-lantern-myeongri'),(select id from public.studio_practitioners where studio_id=(select id from public.saju_studios where slug='ikseon-lantern-myeongri') and display_name='Kim Na-rae'),'general','Year-Ahead Reading','{"en":"Year-Ahead Reading","ko":"신년운세","zh":"流年运势","ja":"年運リーディング","es":"Lectura del año que viene"}'::jsonb,'A month-by-month outlook for the next twelve months: when to push forward and when to rest.','{"en":"A month-by-month outlook for the next twelve months: when to push forward and when to rest.","ko":"앞으로 12개월의 흐름을 월별로 짚어, 나아갈 때와 쉬어갈 때를 알려 드립니다.","zh":"逐月解读未来十二个月：何时进取，何时休整。","ja":"これからの12か月を月ごとに読み、進む時期と休む時期をお伝えします。","es":"Una previsión mes a mes de los próximos doce meses: cuándo avanzar y cuándo descansar."}'::jsonb,45,80000,'KRW',1,true,false,3,true);
